CustomInfo: ConfigSection "Name=Debug Features"
CustomInfo: ConfigParam "Name=DisableDataLog" "Parent=Debug Features" "Priority=Expert" "Type=bool" "Desc=Deshabilita el registro de datos (data/dataLog_<robotName>_<yymmdd>_<hhmmss>)" "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=DisableBatterySimulation" "Parent=Debug Features" "Priority=Expert" "Type=bool" "Desc=Deshabilita la característica que simula el SoC del robot." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=DisableIgnoreLowLaserWhileDocking" "Parent=Debug Features" "Priority=Expert" "Type=bool" "Desc=Deshabilita la característica que ignora los láseres bajos mientras se coloca un LD en la posición de atraque." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=DisableMemoryMonitorRestart" "Parent=Debug Features" "Priority=Expert" "Type=bool" "Desc=Desactiva la característica de reinicio suave de software cuando el monitor de memoria detecta que el uso de memoria física excede el umbral de memoria." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=AcuityPylonRetry" "Parent=Debug Features" "Priority=Expert" "Type=bool" "Desc=Enables acuity camera retry" "Value=true" "Display=Checkbox"
CustomInfo: ConfigParam "Name=Debug" "Parent=Debug Features" "Priority=Expert" "Type=bool" "Desc=Habilita varias opciones de depuración. Añade comandos personalizados para la depuración y también publica datos adicionales para mostrar en las aplicaciones del cliente." "Value=true" "Display=Checkbox"
CustomInfo: ConfigParam "Name=WatchMotorPacket" "Parent=Debug Features" "Priority=Expert" "Type=bool" "Desc=When enabled, motor packet receive is watched, and SEGV shutdown is sent if none received in 30secs." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=WatchDoubleFree" "Parent=Debug Features" "Priority=Expert" "Type=bool" "Desc=When enabled, memory double free is watched, and SIGABRT shutdown is sent if memory is freed twice." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=DebugExternalIO" "Parent=Debug Features" "Priority=Expert" "Type=bool" "Desc=Habilita el registro de la E/S externa, mediante extIODump. Esto solo debe habilitarse durante la depuración." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=DisableExternalIO" "Parent=Debug Features" "Priority=Expert" "Type=bool" "Desc=Deshabilita la característica de E/S externa." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=DisableMarcConfiguration" "Parent=Debug Features" "Priority=Expert" "Type=bool" "Desc=Deshabilita la característica de configuración de MARC" "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=DisableAccelHandler" "Parent=Debug Features" "Priority=Expert" "Type=bool" "Desc=Deshabilita el controlador de aceleración; esto es algo que nos permite registrar los datos del acelerómetro y controla el fallo de vuelco del robot en el lado de ARAM." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=ZipInMapping" "Parent=Debug Features" "Priority=Expert" "Type=bool" "Desc=Comprimir automáticamente los archivos de escaneo y los datos asociados en un archivo contenedor z2d cuando la generación de mapas se ha completado." "Value=true" "Display=Checkbox"
CustomInfo: ConfigParam "Name=DebugMakeServerTcpOnly" "Parent=Debug Features" "Priority=Expert" "Type=bool" "Desc=Usar solo TCP para comunicaciones del servidor. Por lo general, esto debería deshabilitarse a menos que haya problemas con UDP." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=DisableCommMonitor" "Parent=Debug Features" "Priority=Expert" "Type=bool" "Desc=No supervisar la comunicación entre el robot y cualquier aplicación del cliente, como MobileEyes y MobilePlanner." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=DisableDefaultMapComposites" "Parent=Debug Features" "Priority=Expert" "Type=bool" "Desc=Deshabilita todos los objetos de mapa compuesto por defecto." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=LocalizationHistoryDrawing" "Parent=Debug Features" "Priority=Expert" "Type=bool" "Desc=Mantener un historial de los datos de localización para la visualización en MobileEyes." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=AddConfigToMapping" "Parent=Debug Features" "Priority=Expert" "Type=bool" "Desc=Durante el escaneo, registrar los datos de la configuración de Aria en el archivo de escaneo para fines de depuración." "Value=true" "Display=Checkbox"
CustomInfo: ConfigParam "Name=" "Parent=Debug Features" "Priority=Expert" "Type=unknown" "Desc="
CustomInfo: ConfigParam "Name=LogMARCPowerStatusChanges" "Parent=Debug Features" "Priority=Expert" "Type=bool" "Desc=Verdadero para registrar cualquier cambio en los registros del estado de potencia de MARC FPGA, falso para no hacerlo." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=LogMARCCoreVoltageChanges" "Parent=Debug Features" "Priority=Expert" "Type=bool" "Desc=Verdadero para registrar cualquier diferencia en las tensiones de la unidad de comando y control de MARC FPGA mayores a 0,5 V respecto a la tensión de referencia correspondiente, falso para no hacerlo." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=RestartSystemOnFault" "Parent=Debug Features" "Priority=Expert" "Type=bool" "Desc=Verdadero para reiniciar el sistema ante la aparición de un fallo, falso para no hacerlo. Este valor debe ajustarse a verdadero, además de seleccionar aquellos fallos que requieran reinicio del sistema." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=RestartSystemOn_AmpError" "Parent=Debug Features" "Priority=Expert" "Type=bool" "Desc=Verdadero para reiniciar el sistema ante la aparición de este fallo, falso para no hacerlo." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=DisableRobotOnIsGo" "Parent=Debug Features" "Priority=Expert" "Type=bool" "Desc=Marque esto par impedir que el encendido del robot (botón verde) actúe como un botón «ir»." "Value=false" "Display=Checkbox"
CustomInfo: ConfigSection "Name=Debug log"
CustomInfo: ConfigParam "Name=MaxFileSizeMegs" "Parent=Debug log" "Priority=Expert" "Type=double" "Desc=Tamaño máximo (en MB) de un solo inicio de sesión de depuración en formato de texto simple, es decir, antes de la compresión. Esto debe ser menor que TotalMaxMegs y preferencialmente menor que (TotalMaxMegs/2) para almacenar archivos de múltiples ejecuciones." "Value=300" "Min=0"
CustomInfo: ConfigParam "Name=TotalMaxMegs" "Parent=Debug log" "Priority=Expert" "Type=double" "Desc=Tamaño máximo (en MB) asignado para todos los registros de depuración, es decir, la suma de los archivos comprimidos en la carpeta y el archivo actual en formato de texto simple." "Value=700" "Min=0"
CustomInfo: ConfigParam "Name=TotalNumFiles" "Parent=Debug log" "Priority=Expert" "Type=int" "Desc=Cantidad máxima de archivos de registros de depuración que se almacenarán. 0 significa sin límite." "Value=0" "Min=0"
CustomInfo: ConfigParam "Name=RestartWhenFull" "Parent=Debug log" "Priority=Expert" "Type=bool" "Desc=Reiniciar el registro de depuración cuando esté lleno. Por lo general, esto debería deshabilitarse, pero podría ser necesario hacer excepciones para rastrear problemas transitorios. Overrides FreezeWhenFull." "Value=false"
CustomInfo: ConfigParam "Name=RestartWhenFullIfNotLost" "Parent=Debug log" "Priority=Expert" "Type=bool" "Desc=Reiniciar el registro de depuración cuando esté lleno, siempre y cuando el robot no esté extraviado. Por lo general, esto debería deshabilitarse, pero podría ser necesario hacer excepciones para rastrear problemas transitorios. Overrides FreezeWhenFull." "Value=true"
CustomInfo: ConfigParam "Name=FreezeWhenFull" "Parent=Debug log" "Priority=Expert" "Type=bool" "Desc=Fijar el registro de depuración cuando esté lleno. Cuando el registro de depuración se encuentra fijo, la escritura de archivos simplemente se detiene y el archivo no se agrega al contenedor. (Sin embargo, se agregará en el siguiente reinicio). Si se habilita RestartWhenFull, entonces este parámetro se ignorará." "Value=false"
CustomInfo: ConfigParam "Name=RestartAcrossRuns" "Parent=Debug log" "Priority=Expert" "Type=bool" "Desc=Reiniciar el registro de depuración, si está activo, al reiniciar ARAM. Por lo general, esto debería deshabilitarse, pero podría ser necesario hacer excepciones para rastrear problemas transitorios." "Value=false"
CustomInfo: ConfigParam "Name=RestartAcrossRunsIfNotLost" "Parent=Debug log" "Priority=Expert" "Type=bool" "Desc=Reiniciar el registro de depuración, si está activo, al reiniciar ARAM y si el robot no está extraviado. Por lo general, esto debería deshabilitarse, pero podría ser necesario hacer excepciones para rastrear problemas transitorios." "Value=true"
CustomInfo: ConfigSection "Name=Destination Drawing"
CustomInfo: ConfigParam "Name=DrawingMode" "Parent=Destination Drawing" "Priority=Expert" "Type=string" "Desc=Cómo se traza el indicador de destino." "Value=AlwaysOff" "Display=Choices:AlwaysOff;;AlwaysOn;;Flash&&Status:Deprecated"
CustomInfo: ConfigParam "Name=FlashMSec" "Parent=Destination Drawing" "Priority=Expert" "Type=int" "Desc=Velocidad (en ms) a la que se debe proyectar el destino. Válido solamente cuando DrawingMode se configura en Flash. 0 para deshabilitar el diagrama." "Value=1000" "Min=0" "Display=Status:Deprecated"
CustomInfo: ConfigParam "Name=Shape" "Parent=Destination Drawing" "Priority=Expert" "Type=string" "Desc=Forma que se trazará para el indicador de destino." "Value=polyDots" "Display=Choices:polyDots;;polyArrows;;polyLine;;polyPoints;;polySegments&&Status:Deprecated"
CustomInfo: ConfigParam "Name=PrimaryColor" "Parent=Destination Drawing" "Priority=Expert" "Type=int" "Desc=Color primario de diagrama para el indicador de destino." "Value=16776960" "Max=16777215" "Display=Color&&Status:Deprecated"
CustomInfo: ConfigParam "Name=SecondaryColor" "Parent=Destination Drawing" "Priority=Expert" "Type=int" "Desc=Color secundario de diagrama para el indicador de destino." "Value=0" "Max=16777215" "Display=Color&&Status:Deprecated"
CustomInfo: ConfigParam "Name=Size" "Parent=Destination Drawing" "Priority=Expert" "Type=int" "Desc=Tamaño (en mm) del indicador de destino." "Value=800" "Min=0" "Display=Status:Deprecated"
CustomInfo: ConfigParam "Name=Layer" "Parent=Destination Drawing" "Priority=Expert" "Type=int" "Desc=Capa del mapa en que se trazará el indicador de destino." "Value=49" "Min=0" "Display=Status:Deprecated"
CustomInfo: ConfigParam "Name=RefreshTime" "Parent=Destination Drawing" "Priority=Expert" "Type=int" "Desc=Velocidad (en ms) a la que se debe actualizar el indicador de destino." "Value=200" "Min=50" "Display=Status:Deprecated"
CustomInfo: ConfigSection "Name=Docking"
CustomInfo: ConfigParam "Name=SameDockDistanceTolerance" "Parent=Docking" "Priority=Expert" "Type=double" "Desc=Para los casos en que overrideMapName se haya utilizado, las posiciones de atraque dentro de esta distancia y dentro de la SameDockAngleTolerance se cuentan como las mismas con el propósito de ver qué posiciones de atraque están ocupadas por otros robots." "Value=1000" "Min=1" "Display=Status:Deprecated"
CustomInfo: ConfigParam "Name=SameDockAngleTolerance" "Parent=Docking" "Priority=Expert" "Type=double" "Desc=Para los casos en que overrideMapName se haya utilizado, las posiciones de atraque dentro de esta tolerancia angular y dentro de SameDockDistanceTolerance se cuentan como las mismas con el propósito de ver qué posiciones de atraque están ocupadas por otros robots." "Value=10" "Min=1" "Display=Status:Deprecated"
CustomInfo: ConfigParam "Name=NotDockingAutoShutdown" "Parent=Docking" "Priority=Normal" "Type=bool" "Desc=Habilita una característica de apagado automático cuando la posición de atraque no está activa." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=" "Parent=Docking" "Priority=Expert" "Type=unknown" "Desc="
CustomInfo: ConfigParam "Name=AutoDock" "Parent=Docking" "Priority=Normal" "Type=bool" "Desc=Verdadero si debe colocarse en posición de atraque automáticamente" "Value=true"
CustomInfo: ConfigParam "Name=AutoDockStateOfCharge" "Parent=Docking" "Priority=Normal" "Type=double" "Desc=Si el robot se coloca en la posición de atraque automáticamente, el estado de carga en que el robot automáticamente atraca" "Value=25" "Max=100"
CustomInfo: ConfigParam "Name=AutoDockIdleTime" "Parent=Docking" "Priority=Normal" "Type=double" "Desc=Si el robot se coloca en la posición de atraque automáticamente, el tiempo inactivo en minutos hasta colocarse en posición de atraque automáticamente (0 significa que nunca se colocará en posición de atraque automáticamente porque está inactivo)" "Value=15" "Min=0"
CustomInfo: ConfigParam "Name=PreferredDock" "Parent=Docking" "Priority=Normal" "Type=string" "Desc=Si hay un cargador con este nombre, el robot usará esa posición de atraque tanto si OnlyUsePreferredDock es verdadero como si la posición de atraque está disponible.  Si no se cumple alguna de esas condiciones o no existe un cargador con este nombre, se aplicará el comportamiento por defecto para usar la posición de atraque más cercana (por distancia geométrica)." "Value=" "Display=MapItem:DockLynx|SubTypeAndParent|Optional"
CustomInfo: ConfigParam "Name=IncludingDocks" "Parent=Docking" "Priority=Normal" "Type=string" "Desc=A dock that has this including word will be included in the number of docks." "Value=" "Display=RegExp:([a-zA-Z0-9])+$"
CustomInfo: ConfigParam "Name=ExcludingDocks" "Parent=Docking" "Priority=Normal" "Type=string" "Desc=A dock that has this excluding word will be excluded from the number of docks." "Value=" "Display=RegExp:([a-zA-Z0-9])+$"
CustomInfo: ConfigParam "Name=OnlyUsePreferredDock" "Parent=Docking" "Priority=Normal" "Type=bool" "Desc=Si esto es verdadero, el robot sólo usará la posición de atraque preferida (lo que evitará que otros robots lo usen en una configuración de robots múltiples central)" "Value=false" "Display=MapItem:DockLynx|SubTypeAndParent|Optional"
CustomInfo: ConfigParam "Name=DockUntilDoneCharging" "Parent=Docking" "Priority=Normal" "Type=bool" "Desc=Si es verdadero, el robot se colocará en la posición de atraque hasta que se termine de cargar (en modo flotante)" "Value=true"
CustomInfo: ConfigParam "Name=MinutesToChargeFor" "Parent=Docking" "Priority=Normal" "Type=int" "Desc=Si es 0, no termina de cargar en función del tiempo; si es -1, simplemente desatraca tan pronto como esté en posición de atraque (principalmente para pruebas); si es mayor que 0, terminará de cargar después de esos minutos" "Value=0" "Min=-1"
CustomInfo: ConfigParam "Name=StateOfChargeToChargeTo" "Parent=Docking" "Priority=Normal" "Type=double" "Desc=If 0 don't finish charging based on state of charge, if greater than 0 then be done charging after robot's state of charge reaches this point" "Value=0" "Max=100"
CustomInfo: ConfigParam "Name=MinutesBetweenAutoDock" "Parent=Docking" "Priority=Normal" "Type=int" "Desc=Si es 0, no hay límite en la frecuencia en que el robot se puede cargar; si es mayor que 0, transcurrirá esta cantidad de minutos entre el último atraque del robot y el momento en que se colocará en posición de atraque automático" "Value=0" "Min=0"
CustomInfo: ConfigParam "Name=FailedDriveInIgnoreMinutes" "Parent=Docking" "Priority=Normal" "Type=double" "Desc=El número de minutos en que se ignorará una posición de atraque a la que no haya podido conducirse demasiadas veces (FailedDriveInAttemptsBeforeIgnore)...  0 significa no ignorar estas posiciones de atraque." "Value=60" "Min=1"
CustomInfo: ConfigParam "Name=FailedDriveInAttemptsBeforeIgnore" "Parent=Docking" "Priority=Normal" "Type=int" "Desc=El número de veces que se intentará conducir hacia una posición de atraque antes de ignorarla (para FailedDriveInIgnoreMinutes)...  0 significa nunca ignorar una posición de atraque por este motivo." "Value=3" "Min=0"
CustomInfo: ConfigParam "Name=AutoDockShutdownMinutes" "Parent=Docking" "Priority=Normal" "Type=int" "Desc=Esto controla cuánto tiempo debe esperar el robot antes de apagarse si no se puede mover en su camino hacia la posición de atraque en caso de batería baja.  0 significa que no se apaga automáticamente por este motivo; cualquier otro valor significa cuántos minutos debe esperar antes de apagarse" "Value=5" "Max=60"
CustomInfo: ConfigParam "Name=UnforcedDockShutdownMinutes" "Parent=Docking" "Priority=Normal" "Type=int" "Desc=Esto controla cuánto tiempo debe esperar el robot antes de apagarse si no se puede mover en su camino hacia la posición de atraque, si está en posición de atraque porque el robot estaba inactivo o si se realizó una solicitud de posición de atraque explícita.  0 significa que no se apaga automáticamente por este motivo; cualquier otro valor significa cuántos minutos debe esperar antes de apagarse" "Value=10" "Max=60"
CustomInfo: ConfigParam "Name=FinalOffsetX" "Parent=Docking" "Priority=Normal" "Type=double" "Desc=Distancia axial final en mm desde el centro del objetivo hasta el centro del AMR en el sistema de coordenadas del objetivo especificado" "Value=-775" "Max=-300"
CustomInfo: ConfigParam "Name=FinalOffsetY" "Parent=Docking" "Priority=Normal" "Type=double" "Desc=Distancia lateral final en mm desde el centro del objetivo hasta el centro del AMR en el sistema de coordenadas del objetivo especificado" "Value=0" "Max=250"
CustomInfo: ConfigParam "Name=FinalOffsetAngle" "Parent=Docking" "Priority=Normal" "Type=double" "Desc=Rotación final en grados desde el centro del objetivo hasta el centro del AMR en el sistema de coordenadas del objetivo especificado" "Value=180" "Max=200"
CustomInfo: ConfigParam "Name=InitialX" "Parent=Docking" "Priority=Normal" "Type=double" "Desc=Distancia axial inicial en mm desde el centro del objetivo hasta el centro del AMR en el sistema de coordenadas del objetivo especificado" "Value=-2000" "Max=-1000"
CustomInfo: ConfigParam "Name=Timeout" "Parent=Docking" "Priority=Normal" "Type=int" "Desc=Tiempo transcurrido en segundos desde el inicio de la tarea antes del fallo" "Value=60" "Max=54000"
CustomInfo: ConfigParam "Name=PathShape" "Parent=Docking" "Priority=Normal" "Type=string" "Desc=Especifica la silueta de la ruta que recorre el AMR hasta su ubicación final" "Value=PreAlign" "Display=Choices:PreAlign;;Straight;;PreAlign2"
CustomInfo: ConfigParam "Name=SearchMode" "Parent=Docking" "Priority=Normal" "Type=string" "Desc=Especifica el tamaño del área de búsqueda del objetivo que rodea la ubicación inicial" "Value=Normal" "Display=Choices:Normal;;Wide;;Tall;;Minimum;;Maximum;;Rotation&&"
CustomInfo: ConfigParam "Name=MatchMode" "Parent=Docking" "Priority=Normal" "Type=string" "Desc=Especifica la desviación permitida entre la silueta ideal del objetivo y la silueta detectada" "Value=Normal" "Display=Choices:Normal;;Lenient;;Strict&&"
CustomInfo: ConfigParam "Name=FailMode" "Parent=Docking" "Priority=Normal" "Type=string" "Desc=Especifica las condiciones anormales que causan que la tarea falle inmediatamente" "Value=None" "Display=Choices:None;;FailOnEstop"
CustomInfo: ConfigParam "Name=PrimaryLaser" "Parent=Docking" "Priority=Normal" "Type=string" "Desc=Especifica por número qué escáner láser utilizará el AMR para encontrar el objetivo." "Value=Laser_1" "Display=Choices:Laser_1;;Laser_2;;Laser_3;;Laser_4;;Laser_5;;Laser_6"
CustomInfo: ConfigParam "Name=IgnoreDistance" "Parent=Docking" "Priority=Normal" "Type=double" "Desc=Especifica la distancia en mm desde la posición final deseada a la que el AMR dejará de utilizar el objetivo para recibir información sobre la posición." "Value=0" "Max=3000"
CustomInfo: ConfigParam "Name=DebugMode" "Parent=Docking" "Priority=Normal" "Type=string" "Desc=Especifica qué información de la tarea se registra para propósitos de depuración" "Value=Normal" "Display=Choices:None;;Normal;;Moderate;;Extensive;;All"
