CustomInfo: ConfigSection "Name=Driving problem response"
CustomInfo: ConfigParam "Name=BumpStopAndFailEnabled" "Parent=Driving problem response" "Priority=Expert" "Type=bool" "Desc=Cuando se habilita (verdadero), el robot se para por causa de baches y puede fallar debido a ellos Cuando se deshabilita, el robot siempre trata de salir del bache." "Value=false"
CustomInfo: ConfigParam "Name=BumpSecondsToWait" "Parent=Driving problem response" "Priority=Expert" "Type=int" "Desc=Tiempo (en segundos) que el robot espera antes de moverse después de un bache." "Value=5"
CustomInfo: ConfigParam "Name=BumpSecondsToFail" "Parent=Driving problem response" "Priority=Expert" "Type=int" "Desc=Intervalo mínimo aceptable (en segundos) entre baches. Si ocurre más de un bache durante este período de tiempo, el robot no logrará alcanzar su objetivo." "Value=5"
CustomInfo: ConfigParam "Name=EmergencyStopFailEnabled" "Parent=Driving problem response" "Priority=Expert" "Type=bool" "Desc=Falla si se presiona la parada de emergencia." "Value=true"
CustomInfo: ConfigParam "Name=LostFailEnabled" "Parent=Driving problem response" "Priority=Expert" "Type=bool" "Desc=No se puede llegar a un objetivo si el robot se extravía." "Value=true"
CustomInfo: ConfigParam "Name=LostFailEnabled" "Parent=Driving problem response" "Priority=Expert" "Type=bool" "Desc=No se puede llegar a un objetivo si el robot se extravía." "Value=true"
CustomInfo: ConfigSection "Name=Dynamic Obstacles"
CustomInfo: ConfigParam "Name=Enable" "Parent=Dynamic Obstacles" "Priority=Normal" "Type=bool" "Desc=Si esta funcionalidad debe habilitarse" "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=" "Parent=Dynamic Obstacles" "Priority=Expert" "Type=unknown" "Desc="
CustomInfo: ConfigParam "Name=AdditionalLogging" "Parent=Dynamic Obstacles" "Priority=Expert" "Type=bool" "Desc=Si el registro adicional debe habilitarse para la depuración" "Value=false" "Display=Visible:Enable=true&&Checkbox"
CustomInfo: ConfigParam "Name=EnableVariableSize" "Parent=Dynamic Obstacles" "Priority=Expert" "Type=bool" "Desc=Habilita el ajuste automático del tamaño del obstáculo" "Value=true" "Display=Visible:Enable=true&&Checkbox"
CustomInfo: ConfigParam "Name=ObstacleSize" "Parent=Dynamic Obstacles" "Priority=Expert" "Type=int" "Desc=Tamaño típico de los obstáculos rastreados (mm). Este es el tamaño mínimo si se usa tamaño variable." "Value=500" "Min=1" "Display=Visible:Enable=true"
CustomInfo: ConfigParam "Name=TimeHorizon" "Parent=Dynamic Obstacles" "Priority=Expert" "Type=double" "Desc=Cuánto tiempo en el futuro se pueden predecir los movimientos de los obstáculos (seg.)" "Value=7.5" "Max=10" "Display=Visible:Enable=true"
CustomInfo: ConfigParam "Name=MinAvoidanceSpeed" "Parent=Dynamic Obstacles" "Priority=Expert" "Type=double" "Desc=Velocidad mínima para considerar un obstáculo en la planificación de ruta (mm/s)" "Value=300" "Max=2000" "Display=Visible:Enable=true"
CustomInfo: ConfigParam "Name=MinObstacleAge" "Parent=Dynamic Obstacles" "Priority=Expert" "Type=double" "Desc=Edad mínima de un obstáculo antes de tenerlo en consideración para la planificación de ruta (s)" "Value=0.3" "Min=0" "Display=Visible:Enable=true"
CustomInfo: ConfigParam "Name=ForceWithMultirobot" "Parent=Dynamic Obstacles" "Priority=Expert" "Type=bool" "Desc=Forzar el rastreo dinámico cuando los robots múltiples se habilitan mediante el EM" "Value=false" "Display=Visible:Enable=true&&Checkbox"
CustomInfo: ConfigParam "Name=MinReadings" "Parent=Dynamic Obstacles" "Priority=Expert" "Type=int" "Desc=Mínima cantidad de lecturas que se agrupan dentro de la observación de un obstáculo" "Value=3" "Min=3" "Display=Visible:Enable=true"
CustomInfo: ConfigParam "Name=MaxNeighborDistance" "Parent=Dynamic Obstacles" "Priority=Expert" "Type=double" "Desc=Distancia máxima entre lecturas de láser para las cuales pueden estar juntas (mm)" "Value=500" "Max=1000" "Display=Visible:Enable=true"
CustomInfo: ConfigParam "Name=MatchLikelihood" "Parent=Dynamic Obstacles" "Priority=Expert" "Type=string" "Desc=Porcentaje de probabilidad de encontrar una lectura para un obstáculo. Este porcentaje define una distancia proporcional a la desviación estándar del obstáculo. Si un clúster de lecturas de láser está más alejado del obstáculo que esa distancia, no puede ser una observación para ese obstáculo" "Value=95" "Display=Visible:Enable=true&&Choices:99;;97.5;;95;;90;;75"
CustomInfo: ConfigParam "Name=DisableFilterOccGrid" "Parent=Dynamic Obstacles" "Priority=Expert" "Type=bool" "Desc=Deshabilite la cuadrícula de ocupación para filtrar obstáculos estáticos" "Value=false" "Display=Visible:Enable=true&&Checkbox"
CustomInfo: ConfigParam "Name=FilterOccGridThresh" "Parent=Dynamic Obstacles" "Priority=Expert" "Type=double" "Desc=Umbral para cuando una celda se considera estática en la cuadrícula de ocupación filtrante (s). Si algo permanece en una celda individual de la cuadrícula por esta cantidad de segundos, se lo ignora en el rastreo" "Value=0.5" "Min=0" "Display=Visible:Enable=true&&Visible:DisableFilterOccGrid=false"
CustomInfo: ConfigParam "Name=MaxFilterOccGridValue" "Parent=Dynamic Obstacles" "Priority=Expert" "Type=double" "Desc=Valor máximo que puede obtener una celda en la cuadrícula de ocupación del filtro (s)" "Value=2.5" "Min=0" "Display=Visible:Enable=true&&Visible:DisableFilterOccGrid=false"
CustomInfo: ConfigParam "Name=PrimaryLaser" "Parent=Dynamic Obstacles" "Priority=Expert" "Type=string" "Desc=Primary Laser to use" "Value=Laser_1" "Display=Visible:Enable=true&&Choices:Laser_1;;Laser_2;;Laser_3;;Laser_4;;Laser_5;;Laser_6"
CustomInfo: ConfigParam "Name=SecondaryLaser" "Parent=Dynamic Obstacles" "Priority=Expert" "Type=string" "Desc=Secondary Laser to use" "Value=None" "Display=Visible:Enable=true&&Choices:None;;Laser_1;;Laser_2;;Laser_3;;Laser_4;;Laser_5;;Laser_6"
