CustomInfo: ConfigParam "Name=RobotQmUpdateMessages" "Parent=Extra Logging" "Priority=Expert" "Type=bool" "Desc=Habilita el registro (el valor por defecto) para todos los mensajes de QueueUpdate. Éstos aparecerán con el prefijo <QueueUpdate:>" "Value=true" "Display=Checkbox"
CustomInfo: ConfigSection "Name=Feedback"
CustomInfo: ConfigParam "Name=TurningRotVel" "Parent=Feedback" "Priority=Expert" "Type=int" "Desc=Velocidad de rotación mínima (en grados/s) que activa la retroalimentación del giro." "Value=30" "Min=0"
CustomInfo: ConfigParam "Name=DrivingTransVel" "Parent=Feedback" "Priority=Expert" "Type=int" "Desc=Velocidad mínima de traslación o lateral (en mm/s) que activa la retroalimentación para la conducción." "Value=10" "Min=0"
CustomInfo: ConfigParam "Name=LogDebugInfo" "Parent=Feedback" "Priority=Expert" "Type=bool" "Desc=Registrar información de depuración sobre las acciones de retroalimentación." "Value=false"
CustomInfo: ConfigParam "Name=LogDebugVerboseInfo" "Parent=Feedback" "Priority=Expert" "Type=bool" "Desc=Registrar detallado, información minuciosa sobre las acciones de retroalimentación." "Value=false"
