CustomInfo: ConfigParam "Name=ExtraInternalTiMTrace" "Parent=Internal Extra Logging" "Priority=Expert" "Type=bool" "Desc=Enables the dumping of raw trace data. These will show up with the <ArLMS1XX> prefix" "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=LogMARCRegisterReadErrors" "Parent=Internal Extra Logging" "Priority=Expert" "Type=bool" "Desc=Verdadero para registrar cualquier lectura de error en los valores de registro de MARC FPGA, falso para no hacerlo." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=TaskSenderDebug" "Parent=Internal Extra Logging" "Priority=Expert" "Type=bool" "Desc=Habilita el registro de AramServerTaskSender que muestra las tareas enviadas a los clientes." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=DistanceAdjustmentTrace" "Parent=Internal Extra Logging" "Priority=Expert" "Type=bool" "Desc=Habilita el registro adicional para las líneas de ajuste de distancia." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=CentralStandbyPacketIn" "Parent=Internal Extra Logging" "Priority=Expert" "Type=bool" "Desc=Habilita el registro para AramCentralStandby que muestra los recibos y contenido de paquetes CMD." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=CentralStandbyPacketOut" "Parent=Internal Extra Logging" "Priority=Expert" "Type=bool" "Desc=Habilita el registro para AramCentralStandby que muestra el contenido de los paquetes de retorno antes de enviarlos." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=CentralStandbyHelpers" "Parent=Internal Extra Logging" "Priority=Expert" "Type=bool" "Desc=Habilita el registro adicional para AramCentralStandby que muestra los cambios en los reclamos de standbyHelper." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=CentralStandbyVerboseLogs" "Parent=Internal Extra Logging" "Priority=Expert" "Type=bool" "Desc=Habilita el registro detallado adicional para AramCentralStandby que muestra los volcados del registro de reclamos de standbyHelper." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=CentralStandbyClosestStandby" "Parent=Internal Extra Logging" "Priority=Expert" "Type=bool" "Desc=Habilita el registro detallado adicional para AramCentralStandby que muestra el proceso de búsqueda de objetos del mapa para la ubicación de espera más cercana." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=CentralStandbyManagedSectors" "Parent=Internal Extra Logging" "Priority=Expert" "Type=bool" "Desc=Habilita el registro detallado adicional para AramCentralStandby que muestra la creación de asociaciones ManagedDestination/ManagedMotion ante eventos de cambio de mapa." "Value=true" "Display=Checkbox"
CustomInfo: ConfigParam "Name=CentralStandbyStandbyClaims" "Parent=Internal Extra Logging" "Priority=Expert" "Type=bool" "Desc=Habilita el registro detallado adicional para AramCentralStandby que muestra el estado de disponibilidad de la ubicación de espera durante la secuencia de registro detallado. (Requiere 'CentralStandbyVerboseLogs')" "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=FaultsExtraDebug" "Parent=Internal Extra Logging" "Priority=Expert" "Type=bool" "Desc=Habilita el registro de depuración adicional para fallos." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=AcapelaDebug" "Parent=Internal Extra Logging" "Priority=Expert" "Type=bool" "Desc=Habilita el registro de depuración adicional para Acapela." "Value=true" "Display=Checkbox"
CustomInfo: ConfigParam "Name=RouteDataTrace" "Parent=Internal Extra Logging" "Priority=Expert" "Type=bool" "Desc=Habilita una ruta de registro adicional para las rutas de código. Éstos aparecerán con el prefijo <AramRouteData>" "Value=false" "Display=Checkbox"
