CustomInfo: ConfigParam "Name=QmArclSocketRemove" "Parent=Internal Extra Logging" "Priority=Expert" "Type=bool" "Desc=Habilita el registro adicional en la llamada de eliminación de socket. Éstos aparecerán con el prefijo <AramCentralQMArcl>" "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=QmArclLocks" "Parent=Internal Extra Logging" "Priority=Expert" "Type=bool" "Desc=Habilita el registro de bloqueo/desbloqueo de depuración. Éstos aparecerán con el prefijo <AramCentralQMArcl>" "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=QmArclLocks" "Parent=Internal Extra Logging" "Priority=Expert" "Type=bool" "Desc=Habilita el registro de bloqueo/desbloqueo de depuración. Éstos aparecerán con el prefijo <AramCentralQMArcl>" "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=RobotQmClientMgrFwdLocks" "Parent=Internal Extra Logging" "Priority=Expert" "Type=bool" "Desc=Habilita el registro de bloqueo/desbloqueo de depuración. Estos aparecerán con el prefijo <AramQmClientMgrFwd>" "Value=false" "Display=Checkbox"
CustomInfo: ConfigSection "Name=Internal Testing Features"
CustomInfo: ConfigParam "Name=WaitAfterConnectionRejectedInMins" "Parent=Internal Testing Features" "Priority=Expert" "Type=int" "Desc=Specify time in minutes that robot waits to make another connection with the current one rejected due to number of connected robots having reached licensed robot count" "Value=30" "Max=60"
CustomInfo: ConfigSection "Name=Language/Location"
CustomInfo: ConfigParam "Name=RobotLanguage" "Parent=Language/Location" "Priority=Normal" "Type=string" "Desc=El idioma de la pantalla táctil del robot y que se utiliza en la información enviada por el robot a los clientes, por ej., MobilePlanner. Si el idioma solo es compatible con la pantalla táctil del robot, pero todavía no lo es con todo el software del robot (por ej., francés, alemán), la información enviada por el robot a los clientes será por defecto en inglés, aunque la pantalla táctil usará el idioma seleccionado. Si se modifica el valor, el software se reiniciará para que el nuevo idioma tenga efecto. Este parámetro no determina el idioma de la síntesis de voz." "Value=Spanish" "Display=Choices:English;;Chinese-Simplified;;Chinese-Traditional;;Czech;;French;;German;;Italian;;Japanese;;Korean;;Polish;;Spanish"
CustomInfo: ConfigParam "Name=Voice_Selection" "Parent=Language/Location" "Priority=Expert" "Type=unknown" "Desc=Selección de voz para la síntesis de voz."
CustomInfo: ConfigSection "Name=Laser_1"
CustomInfo: ConfigParam "Name=LaserAutoConnect" "Parent=Laser_1" "Priority=Expert" "Type=bool" "Desc=Laser_1 existe y debería de conectarse automáticamente durante el inicio." "Value=true" "Display=Checkbox"
CustomInfo: ConfigParam "Name=" "Parent=Laser_1" "Priority=Factory" "Type=unknown" "Desc="
CustomInfo: ConfigParam "Name=LaserX" "Parent=Laser_1" "Priority=Expert" "Type=int" "Desc=Ubicación (en mm) de este láser en X (+ delantero, - trasero) en relación con el centro idealizado de rotación del robot." "Value=267" "Display=Visible:LaserAutoConnect=true"
CustomInfo: ConfigParam "Name=LaserY" "Parent=Laser_1" "Priority=Expert" "Type=int" "Desc=Ubicación (en mm) de este transductor de láser en Y (+ izquierda, - derecha) en relación con el centro idealizado de rotación del robot." "Value=0" "Display=Visible:LaserAutoConnect=true"
CustomInfo: ConfigParam "Name=LaserTh" "Parent=Laser_1" "Priority=Expert" "Type=double" "Desc=Rotación (en grados) de este láser (+ en sentido antihorario, - en sentido horario)." "Value=0" "Max=180" "Display=Visible:LaserAutoConnect=true"
CustomInfo: ConfigParam "Name=LaserZ" "Parent=Laser_1" "Priority=Expert" "Type=int" "Desc=Altura (en mm) del láser desde el suelo. 0 significa desconocida." "Value=190" "Min=0" "Display=Visible:LaserAutoConnect=true"
CustomInfo: ConfigParam "Name=LaserIgnore" "Parent=Laser_1" "Priority=Expert" "Type=string" "Desc=Ángulos (en grados) a los cuales ignorar las lecturas, +/- un grado. Los intervalos se introducen como inicio:fin. Los intervalos múltiples se pueden separar con comas." "Value=-135:-120,120:135" "Display=Visible:LaserAutoConnect=true"
CustomInfo: ConfigParam "Name=LaserFlipped" "Parent=Laser_1" "Priority=Expert" "Type=bool" "Desc=Laser_1 está al revés." "Value=true" "Display=Visible:LaserAutoConnect=true&&Checkbox"
CustomInfo: ConfigParam "Name=LaserType" "Parent=Laser_1" "Priority=Expert" "Type=string" "Desc=Tipo de láser." "Value=os32c" "Display=Visible:LaserAutoConnect=true&&Choices:s3series;;tim3XX;;tim510;;tim551;;os32c;;os32cethernet"
CustomInfo: ConfigParam "Name=LaserPortType" "Parent=Laser_1" "Priority=Expert" "Type=string" "Desc=Tipo de puerto en que está el láser." "Value=serial422" "Display=Visible:LaserAutoConnect=true&&Choices:serial;;serial422;;tcp"
CustomInfo: ConfigParam "Name=LaserPort" "Parent=Laser_1" "Priority=Expert" "Type=string" "Desc=Puerto en que está el láser." "Value=/dev/ttyUSB4" "Display=Visible:LaserAutoConnect=true"
CustomInfo: ConfigParam "Name=LaserPowerOutput" "Parent=Laser_1" "Priority=Expert" "Type=string" "Desc=Salida de potencia que controla la potencia de este láser." "Value=" "Display=Visible:LaserAutoConnect=true&&Choices:;;Main_Laser_Power;;HMI_Power;;WheelLight_Power;;Sonar_1_Power;;Sonar_2_Power;;USB_1_and_2_Power;;USB_3_Power;;Vertical_Laser_Power;;Foot_Laser_Power;;Battery_Out_1;;Battery_Out_2;;Battery_Out_3_and_4;;Aux_5V;;Aux_12V;;Aux_20V;;Audio_Power"
CustomInfo: ConfigParam "Name=LaserStartingBaudChoice" "Parent=Laser_1" "Priority=Expert" "Type=string" "Desc=StartingBaud para este láser. Deje en blanco para usar el valor por defecto." "Value=921600" "Display=Visible:LaserAutoConnect=true"
CustomInfo: ConfigParam "Name=LaserAutoBaudChoice" "Parent=Laser_1" "Priority=Expert" "Type=string" "Desc=AutoBaud para este láser. Deje en blanco para usar el valor por defecto." "Value=" "Display=Visible:LaserAutoConnect=true"
CustomInfo: ConfigParam "Name=LaserIsLow" "Parent=Laser_1" "Priority=Expert" "Type=bool" "Desc=Si este láser es un láser bajo para detectar obstáculos de poca altura (como pies, palés, etc.)." "Value=false" "Display=Checkbox&&Visible:LaserAutoConnect=true"
CustomInfo: ConfigParam "Name=LaserIsForCartSensing" "Parent=Laser_1" "Priority=Expert" "Type=bool" "Desc=Si este láser es uno que se monta en la plataforma superior para detectar el carrito.  El láser se ignora en la planificación de rutas." "Value=false" "Display=Checkbox&&Visible:LaserAutoConnect=true"
CustomInfo: ConfigParam "Name=LaserIsTilted" "Parent=Laser_1" "Priority=Expert" "Type=bool" "Desc=El láser se inclina para detectar obstáculos positivos; es decir, aquellos sobre el suelo." "Value=false" "Display=Checkbox&&Visible:LaserAutoConnect=true"
CustomInfo: ConfigParam "Name=TiltedFlipped" "Parent=Laser_1" "Priority=Expert" "Type=bool" "Desc=Voltea las lecturas en bruto del láser al revés inclinado. Solo es aplicable cuando se habilitan LaserIsTilted o LaserIsTiltedNegativeSensor." "Value=false" "Display=Checkbox&&Visible:LaserAutoConnect=true"
CustomInfo: ConfigParam "Name=LaserIsTiltedNegativeSensor" "Parent=Laser_1" "Priority=Expert" "Type=bool" "Desc=Los láseres inclinados pueden usarse como un método de protección secundaria contra el encuentro de los robots con obstáculos negativos (como posiciones de atraque, escaleras, etc.). Esta detección solo es posible en el plano de detección del láser inclinado y no se puede usar como el único medio para evitar obstáculos negativos. Siempre deberían de usarse otros métodos de protección primaria. Hable con su proveedor de robots antes de usar esta característica. Esta es una característica beta experimental." "Value=false" "Display=Checkbox&&Visible:LaserAutoConnect=true"
CustomInfo: ConfigParam "Name=LaserIsFiltered" "Parent=Laser_1" "Priority=Expert" "Type=bool" "Desc=Las lecturas del láser deben filtrarse. Esto podría tener que habilitarse cuando el láser puede detectar las ruedas del robot (por ejemplo). Si se habilitan LaserIsTilted o LaserIsTiltedNegativeSensor, entonces esta opción se ignorará." "Value=false" "Display=Checkbox&&Visible:LaserAutoConnect=true"
CustomInfo: ConfigParam "Name=LaserIsFiltered_v2" "Parent=Laser_1" "Priority=Expert" "Type=bool" "Desc=Las lecturas del láser deben filtrarse con el filtro de la versión 2 que funciona incluso cuando se habilita LaserIsTilted o LaserIsTiltedNegativeSensor. Como el parámetro original LaserIsFiltered, esto podría tener que habilitarse cuando el láser puede detectar las ruedas del robot (por ejemplo). Cuando se habilita, esto anula el valor de LaserIsFiltered." "Value=true" "Display=Checkbox&&Visible:LaserAutoConnect=true"
CustomInfo: ConfigSection "Name=Laser_1 Settings"
CustomInfo: ConfigParam "Name=" "Parent=Laser_1 Settings" "Priority=Expert" "Type=unknown" "Desc="
CustomInfo: ConfigParam "Name=Filter_v2_Disable" "Parent=Laser_1 Settings" "Priority=Expert" "Type=bool" "Desc=Si este filtro debe deshabilitarse.  Esto es redundante con la opción de habilitar en las secciones de láser en Elementos físicos del robot, pero existe para que el filtrado pueda alternarse fácilmente en una flota entera." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=Filter_v2_MinValidReading" "Parent=Laser_1 Settings" "Priority=Expert" "Type=int" "Desc=Filtrar CUALQUIERA de las lecturas que están más cerca que esta, de modo que no se usan para otro filtrado (lo cual significa que es para compensar los problemas del láser más que por objetos reales vistos). (mm)" "Value=0" "Min=0" "Display=Visible:Filter_v2_Disable=false"
CustomInfo: ConfigParam "Name=Filter_v2_Width" "Parent=Laser_1 Settings" "Priority=Expert" "Type=double" "Desc=La anchura (en relación con el rayo del láser) de un área en mm que se debe inspeccionar en busca de lecturas cercanas para indicar que esta lectura no debería filtrarse. Los valores negativos desactivan este filtrado.  (mm)" "Value=10" "Max=200" "Display=Visible:Filter_v2_Disable=false"
CustomInfo: ConfigParam "Name=Filter_v2_CloseLength" "Parent=Laser_1 Settings" "Priority=Expert" "Type=double" "Desc=The difference in distance in mm from the laser that makes a reading count as 'close' to a reading being checked. (mm)" "Value=250" "Max=1000" "Display=Visible:Filter_v2_Disable=false"
CustomInfo: ConfigParam "Name=Filter_v2_SingleMaxDistFromLaser" "Parent=Laser_1 Settings" "Priority=Expert" "Type=double" "Desc=Filter out single readings that do not have a close neighbor out to this distance from the laser itself (this does not take into account the position of the laser on the robot).  Negative values turn off this filtering.  (mm)" "Value=-1" "Min=-1" "Display=Visible:Filter_v2_Disable=false"
CustomInfo: ConfigParam "Name=Filter_v2_SingleCloseLength" "Parent=Laser_1 Settings" "Priority=Expert" "Type=double" "Desc=The difference in distance in mm from the laser that makes a reading count as 'close' to a reading being checked. (mm)" "Value=250" "Max=1000" "Display=Visible:Filter_v2_Disable=false"
CustomInfo: ConfigParam "Name=MinDistBetweenCurrent" "Parent=Laser_1 Settings" "Priority=Expert" "Type=double" "Desc=Distancia mínima (en mm) entre las lecturas actuales almacenadas." "Value=0"
CustomInfo: ConfigParam "Name=CumulativeBufferSize" "Parent=Laser_1 Settings" "Priority=Expert" "Type=int" "Desc=Número máximo de lecturas que se almacenan en la protección acumulativa Los cambios en este valor pueden tener un efecto significativo en el uso de CPU debido a la sobrecarga asociada con la limpieza de las lecturas acumuladas." "Value=200"
CustomInfo: ConfigParam "Name=MaxSecondsToKeepCumulative" "Parent=Laser_1 Settings" "Priority=Expert" "Type=int" "Desc=Duración (en segundos) en que se almacenan las lecturas acumuladas. Si es 0 o negativo, las lecturas acumuladas no se descartarán con base en la antigüedad." "Value=30"
CustomInfo: ConfigParam "Name=MaxDistToKeepCumulative" "Parent=Laser_1 Settings" "Priority=Expert" "Type=double" "Desc=Distancia máxima (en mm) permitida entre la posición actual y las lecturas acumuladas almacenadas. Si una lectura supera esta distancia, se descartará. Si es 0 o negativo, las lecturas acumuladas no se descartarán con base en la distancia." "Value=4000"
CustomInfo: ConfigParam "Name=MinDistBetweenCumulative" "Parent=Laser_1 Settings" "Priority=Expert" "Type=double" "Desc=Distancia mínima (en mm) entre las lecturas acumuladas. Si es 0 o negativo, las lecturas no se descartarán debido a su proximidad entre sí." "Value=200"
CustomInfo: ConfigParam "Name=MaxInsertDistCumulative" "Parent=Laser_1 Settings" "Priority=Expert" "Type=double" "Desc=Distancia máxima (en mm) permitida entre la posición actual del robot y la nueva lectura acumulada. Si una lectura supera esta distancia, no se insertará en las lecturas acumuladas." "Value=3000"
CustomInfo: ConfigParam "Name=CumulativeCleanDist" "Parent=Laser_1 Settings" "Priority=Expert" "Type=double" "Desc=Distancia mínima (en mm) entre las lecturas acumuladas almacenadas y los haces actuales. Si esto es 0 o negativo, las lecturas no se descartarán debido a su proximidad con los haces." "Value=75"
CustomInfo: ConfigParam "Name=CumulativeCleanInterval" "Parent=Laser_1 Settings" "Priority=Expert" "Type=int" "Desc=Intervalo (en milisegundos) después del que se borran las lecturas acumuladas." "Value=1000"
CustomInfo: ConfigParam "Name=UseCustomMaxRange" "Parent=Laser_1 Settings" "Priority=Expert" "Type=bool" "Desc=Cuando se habilita (verdadero), el CustomMaxRange especificado se utiliza en vez del rango máximo por defecto del sensor. (Usar con precaución. Esta es una opción avanzada que solo deberían habilitar usuarios expertos." "Value=false"
CustomInfo: ConfigParam "Name=CustomMaxRange" "Parent=Laser_1 Settings" "Priority=Expert" "Type=int" "Desc=Intervalo máximo personalizado (en mm) usado para el sensor. Esto se aplica solo cuando UseCustomMaxRange se ha habilitado. 0 significa que no hay un valor máximo." "Value=0" "Min=0" "Display=Visible:UseCustomMaxRange=true"
CustomInfo: ConfigSection "Name=Laser_2"
CustomInfo: ConfigParam "Name=LaserAutoConnect" "Parent=Laser_2" "Priority=Expert" "Type=bool" "Desc=Laser_2 existe y debería de conectarse automáticamente durante el inicio." "Value=true" "Display=Checkbox"
