CustomInfo: ConfigParam "Name=LaserX" "Parent=Laser_2" "Priority=Expert" "Type=int" "Desc=Ubicación (en mm) de este láser en X (+ delantero, - trasero) en relación con el centro idealizado de rotación del robot." "Value=267" "Display=Visible:LaserAutoConnect=true"
CustomInfo: ConfigParam "Name=LaserY" "Parent=Laser_2" "Priority=Expert" "Type=int" "Desc=Ubicación (en mm) de este transductor de láser en Y (+ izquierda, - derecha) en relación con el centro idealizado de rotación del robot." "Value=0" "Display=Visible:LaserAutoConnect=true"
CustomInfo: ConfigParam "Name=LaserTh" "Parent=Laser_2" "Priority=Expert" "Type=double" "Desc=Rotación (en grados) de este láser (+ en sentido antihorario, - en sentido horario)." "Value=0" "Max=180" "Display=Visible:LaserAutoConnect=true"
CustomInfo: ConfigParam "Name=LaserZ" "Parent=Laser_2" "Priority=Expert" "Type=int" "Desc=Altura (en mm) del láser desde el suelo. 0 significa desconocida." "Value=58" "Min=0" "Display=Visible:LaserAutoConnect=true"
CustomInfo: ConfigParam "Name=LaserIgnore" "Parent=Laser_2" "Priority=Expert" "Type=string" "Desc=Ángulos (en grados) a los cuales ignorar las lecturas, +/- un grado. Los intervalos se introducen como inicio:fin. Los intervalos múltiples se pueden separar con comas." "Value=-63:-180,180:63" "Display=Visible:LaserAutoConnect=true"
CustomInfo: ConfigParam "Name=LaserFlipped" "Parent=Laser_2" "Priority=Expert" "Type=bool" "Desc=Laser_2 está al revés." "Value=true" "Display=Visible:LaserAutoConnect=true&&Checkbox"
CustomInfo: ConfigParam "Name=LaserType" "Parent=Laser_2" "Priority=Expert" "Type=string" "Desc=Tipo de láser." "Value=tim3XX" "Display=Visible:LaserAutoConnect=true&&Choices:s3series;;tim3XX;;tim510;;tim551;;os32c;;os32cethernet"
CustomInfo: ConfigParam "Name=LaserPortType" "Parent=Laser_2" "Priority=Expert" "Type=string" "Desc=Tipo de puerto en que está el láser." "Value=serial" "Display=Visible:LaserAutoConnect=true&&Choices:serial;;serial422;;tcp"
CustomInfo: ConfigParam "Name=LaserPort" "Parent=Laser_2" "Priority=Expert" "Type=string" "Desc=Puerto en que está el láser." "Value=/dev/ttyUSB7" "Display=Visible:LaserAutoConnect=true"
CustomInfo: ConfigParam "Name=LaserPowerOutput" "Parent=Laser_2" "Priority=Expert" "Type=string" "Desc=Salida de potencia que controla la potencia de este láser." "Value=Foot_Laser_Power" "Display=Visible:LaserAutoConnect=true&&Choices:;;Main_Laser_Power;;HMI_Power;;WheelLight_Power;;Sonar_1_Power;;Sonar_2_Power;;USB_1_and_2_Power;;USB_3_Power;;Vertical_Laser_Power;;Foot_Laser_Power;;Battery_Out_1;;Battery_Out_2;;Battery_Out_3_and_4;;Aux_5V;;Aux_12V;;Aux_20V;;Audio_Power"
CustomInfo: ConfigParam "Name=LaserStartingBaudChoice" "Parent=Laser_2" "Priority=Expert" "Type=string" "Desc=StartingBaud para este láser. Deje en blanco para usar el valor por defecto." "Value=" "Display=Visible:LaserAutoConnect=true"
CustomInfo: ConfigParam "Name=LaserAutoBaudChoice" "Parent=Laser_2" "Priority=Expert" "Type=string" "Desc=AutoBaud para este láser. Deje en blanco para usar el valor por defecto." "Value=" "Display=Visible:LaserAutoConnect=true"
CustomInfo: ConfigParam "Name=LaserIsLow" "Parent=Laser_2" "Priority=Expert" "Type=bool" "Desc=Si este láser es un láser bajo para detectar obstáculos de poca altura (como pies, palés, etc.)." "Value=true" "Display=Checkbox&&Visible:LaserAutoConnect=true"
