CustomInfo: ConfigParam "Name=MaxSecondsToKeepCurrent" "Parent=Sonar Settings" "Priority=Expert" "Type=int" "Desc=Duración (en segundos) en que se almacenan las lecturas actuales. Si es 0 o negativo, las lecturas no se descartarán automáticamente con base en la antigüedad." "Value=5"
CustomInfo: ConfigParam "Name=MinDistBetweenCurrent" "Parent=Sonar Settings" "Priority=Expert" "Type=double" "Desc=Distancia mínima (en mm) entre las lecturas actuales almacenadas." "Value=0"
CustomInfo: ConfigParam "Name=UseCustomMaxRange" "Parent=Sonar Settings" "Priority=Expert" "Type=bool" "Desc=Cuando se habilita (verdadero), el CustomMaxRange especificado se utiliza en vez del rango máximo por defecto del sensor. (Usar con precaución. Esta es una opción avanzada que solo deberían habilitar usuarios expertos." "Value=false"
CustomInfo: ConfigParam "Name=CustomMaxRange" "Parent=Sonar Settings" "Priority=Expert" "Type=int" "Desc=Intervalo máximo personalizado (en mm) usado para el sensor. Esto se aplica solo cuando UseCustomMaxRange se ha habilitado. 0 significa que no hay un valor máximo." "Value=0" "Min=0" "Display=Visible:UseCustomMaxRange=true"
CustomInfo: ConfigSection "Name=SonarBoard_1"
CustomInfo: ConfigParam "Name=SonarAutoConnect" "Parent=SonarBoard_1" "Priority=Expert" "Type=bool" "Desc=SonarBoard_1 existe y debería de conectarse automáticamente durante el inicio." "Value=true" "Display=Checkbox"
CustomInfo: ConfigParam "Name=" "Parent=SonarBoard_1" "Priority=Factory" "Type=unknown" "Desc="
CustomInfo: ConfigParam "Name=SonarBoardType" "Parent=SonarBoard_1" "Priority=Expert" "Type=string" "Desc=Tipo de panel de sónar." "Value=mtx" "Display=Visible:SonarAutoConnect=true&&Choices:mtx;;tof"
CustomInfo: ConfigParam "Name=SonarBoardPortType" "Parent=SonarBoard_1" "Priority=Expert" "Type=string" "Desc=Tipo de puerto en que se encuentra el sónar." "Value=serial422" "Display=Visible:SonarAutoConnect=true&&Choices:serial;;serial422;;tcp"
CustomInfo: ConfigParam "Name=SonarBoardPort" "Parent=SonarBoard_1" "Priority=Expert" "Type=string" "Desc=Puerto en que se encuentra el sónar." "Value=/dev/ttyUSB2" "Display=Visible:SonarAutoConnect=true"
CustomInfo: ConfigParam "Name=SonarBoardPowerOutput" "Parent=SonarBoard_1" "Priority=Expert" "Type=string" "Desc=Salida de potencia que controla esta potencia del panel de sónar." "Value=Sonar_1_Power" "Display=Visible:SonarAutoConnect=true&&Choices:;;Main_Laser_Power;;HMI_Power;;WheelLight_Power;;Sonar_1_Power;;Sonar_2_Power;;USB_1_and_2_Power;;USB_3_Power;;Vertical_Laser_Power;;Foot_Laser_Power;;Battery_Out_1;;Battery_Out_2;;Battery_Out_3_and_4;;Aux_5V;;Aux_12V;;Aux_20V;;Audio_Power"
CustomInfo: ConfigParam "Name=SonarBaud" "Parent=SonarBoard_1" "Priority=Expert" "Type=int" "Desc=Velocidad de baudios para la comunicación con el panel del sónar. (9600, 19200, 38400, etc.)." "Value=115200" "Display=Visible:SonarAutoConnect=true"
CustomInfo: ConfigParam "Name=SonarDelay" "Parent=SonarBoard_1" "Priority=Expert" "Type=int" "Desc=Retraso del sónar (en ms)" "Value=2" "Max=10" "Display=Visible:SonarAutoConnect=true"
CustomInfo: ConfigParam "Name=SonarGain" "Parent=SonarBoard_1" "Priority=Expert" "Type=int" "Desc=Ganancia por defecto del sónar para el panel, intervalo 0-31." "Value=10" "Max=31" "Display=Visible:SonarAutoConnect=true"
CustomInfo: ConfigParam "Name=SonarDetectionThreshold" "Parent=SonarBoard_1" "Priority=Expert" "Type=int" "Desc=Umbral de detección del sónar por defecto del sónar para el panel." "Value=650" "Max=65535" "Display=Visible:SonarAutoConnect=true"
CustomInfo: ConfigParam "Name=SonarMaxRange" "Parent=SonarBoard_1" "Priority=Expert" "Type=int" "Desc=Intervalo máximo del sónar por defecto para el panel." "Value=4334" "Max=4335" "Display=Visible:SonarAutoConnect=true"
CustomInfo: ConfigSection "Name=Speech Synthesis"
CustomInfo: ConfigParam "Name=DefaultVoiceParameters" "Parent=Speech Synthesis" "Priority=Expert" "Type=bool" "Desc=Si se configura, se usarán los valores de los parámetros por defecto en las voces. Si no se configura, se usarán valores personalizados de esta sección." "Value=true" "Display=Checkbox"
CustomInfo: ConfigParam "Name=SynthesisPitch" "Parent=Speech Synthesis" "Priority=Expert" "Type=int" "Desc=Controla los agudos de la voz.  Un valor más bajo indica un tono más grave; un valor más alto indica un tono más agudo." "Value=100" "Max=200"
CustomInfo: ConfigParam "Name=SynthesisRate" "Parent=Speech Synthesis" "Priority=Expert" "Type=int" "Desc=Controla la velocidad de habla de la voz sintética. Un valor más alto indica una velocidad de habla mayor." "Value=20" "Max=200"
CustomInfo: ConfigParam "Name=SynthesisVolume" "Parent=Speech Synthesis" "Priority=Expert" "Type=int" "Desc=Controla el volumen de la voz sintética." "Value=1000" "Max=65535"
CustomInfo: ConfigParam "Name=SynthesisShapingRange" "Parent=Speech Synthesis" "Priority=Expert" "Type=int" "Desc=Es similar al tono y se usa en voces que no admiten el control de tono. Esto es un porcentaje de la longitud del tracto de voz normal utilizado en función del género y controla la forma de la voz al cambiar la longitud del tracto vocal. Puede dar como resultado voces no humanas." "Value=100" "Max=200"
CustomInfo: ConfigParam "Name=ForceSelectorBreak" "Parent=Speech Synthesis" "Priority=Expert" "Type=bool" "Desc=Si la herramienta de síntesis está sintetizando oraciones largas sin signos de puntuación, puede generar pausas antes de que comience la vocalización. Activar esto hace que la síntesis sea más rápida en esos casos." "Value=false"
CustomInfo: ConfigParam "Name=PreSel" "Parent=Speech Synthesis" "Priority=Expert" "Type=int" "Desc=Controla la calidad de la voz sintética. Aumentar este parámetro incrementa la calidad de la voz, pero también aumenta el uso de la CPU y memoria." "Value=100" "Max=200"
CustomInfo: ConfigSection "Name=Standby"
CustomInfo: ConfigParam "Name=BlacklistStandbyDistance" "Parent=Standby" "Priority=Expert" "Type=int" "Desc=Si el robot falla al ir a un objetivo en ubicación de espera, pero se acerca a esta distancia o menos, entonces la ubicación de espera se añadirá a la lista negra durante un periodo.  Esto debe ser mayor que Ajustes de planificación de ruta->GoalOccupiedFailDistance, probablemente por un factor de dos (ya que esta es una distancia recta frente al robot).  0 deshabilita este comportamiento" "Value=2000" "Min=0"
CustomInfo: ConfigParam "Name=FreeStandbyPaddingDistance" "Parent=Standby" "Priority=Expert" "Type=int" "Desc=Si el robot está usando una ubicación de espera con múltiples robots, liberará la ubicación de espera para otros robots después de que el robot esté en su longitud + este espacio libre adicional fuera del objetivo." "Value=200" "Min=0"
CustomInfo: ConfigParam "Name=BlacklistStandbyMinutes" "Parent=Standby" "Priority=Expert" "Type=double" "Desc=La cantidad de minutos 1) para añadir a la lista negra una ubicación de espera para todos los robots si dos robots no han podido alcanzarla (también dentro de esta cantidad de minutos) 2) para añadir a la lista negra una ubicación de espera para un robot que falló al dirigirse a dicha ubicación.  El 0 deshabilita esta característica." "Value=5" "Min=0"
CustomInfo: ConfigParam "Name=PreferredParkingMaxDistance" "Parent=Standby" "Priority=Expert" "Type=double" "Desc=La distancia (en metros) después de la cual los robots ignorarán una ubicación de espera PreferredParking al buscar un lugar para estacionar. Esto garantiza que los robots no estén conduciendo frecuentemente a través de todo el sitio para estacionar en el lugar de recogida." "Value=50" "Min=0"
CustomInfo: ConfigSection "Name=Target Definition"
CustomInfo: ConfigParam "Name=2D_TargetList" "Parent=Target Definition" "Priority=Normal" "Type=unknown" "Desc=2D target list."
CustomInfo: ConfigSection "Name=Task Features"
CustomInfo: ConfigParam "Name=LegacyPauseWaitTasks" "Parent=Task Features" "Priority=Expert" "Type=bool" "Desc=Cuando se habilita, use la implementación de pausa/espera heredada en vez de la versión actualizada. (Esta es una característica avanzada que debería habilitarse solo si se encuentran problemas con la implementación actual. Si este es el caso, notifique su proveedor de robot.)" "Value=false" "Display=Checkbox&&Status:Deprecated"
CustomInfo: ConfigParam "Name=PauseCompatibility" "Parent=Task Features" "Priority=Expert" "Type=bool" "Desc=Cuando se habilita, proporciona compatibilidad retroactiva para la tarea de pausa heredada. Note que la tarea de pausa se ha vuelto obsoleta. Debería ser sustituida por la nueva tarea de waitIndefinitely. Esta opción de compatibilidad podría eliminarse en una futura versión de ARAM." "Value=false" "Display=Checkbox&&Status:Deprecated"
CustomInfo: ConfigParam "Name=LegacyWaitBehavior" "Parent=Task Features" "Priority=Expert" "Type=bool" "Desc=Cuando se habilita, usa el comportamiento de espera heredada. Esto ocasionaba que los robots esperaran durante un segundo más que el tiempo de espera especificado y era el comportamiento estándar en las versiones de ARAM 4.4 y anteriores." "Value=false" "Display=Checkbox&&Status:Deprecated"
CustomInfo: ConfigParam "Name=TriangleDriveToAdvanced" "Parent=Task Features" "Priority=Expert" "Type=bool" "Desc=Habilitar la tarea triangleDriveToAdvanced. Esto es similar a la tarea triangleDriveTo, pero también proporciona los parámetros de la tarea para todas las opciones de configuración. Se prevé principalmente para usarse dentro de macros." "Value=true" "Display=Checkbox&&Status:Deprecated"
CustomInfo: ConfigParam "Name=TriangleDriveToAdvancedProx" "Parent=Task Features" "Priority=Expert" "Type=bool" "Desc=Habilitar la tarea triangleDriveToAdvancedProx. Esto es similar a la tarea triangleDriveToAdvanced, pero también proporciona compatibilidad con los sensores de proximidad. Si se define algún sensor de proximidad, el robot se moverá hasta que uno se active." "Value=false" "Display=Checkbox&&Status:Deprecated"
CustomInfo: ConfigParam "Name=TriangleDriveTo" "Parent=Task Features" "Priority=Expert" "Type=bool" "Desc=Habilitar la tarea triangleDriveTo." "Value=true" "Display=Checkbox&&Status:Deprecated"
CustomInfo: ConfigParam "Name=TriangleDriveTo2" "Parent=Task Features" "Priority=Expert" "Type=bool" "Desc=Habilitar una tarea de conducción hacia un objetivo triangular adicional (triangleDriveTo2). triangleDriveTo2 es en esencia igual a triangleDriveTo. Su finalidad principal es permitir un segundo conjunto de valores de configuración." "Value=false" "Display=Checkbox&&Status:Deprecated"
CustomInfo: ConfigParam "Name=TriangleTargetTask" "Parent=Task Features" "Priority=Expert" "Type=bool" "Desc=Habilita la tarea TriangleTargetDrive generalizada, la cual busca un triángulo en el entorno y posiciona el robot relativo a él." "Value=false" "Display=Checkbox&&Status:Deprecated"
CustomInfo: ConfigParam "Name=Move2" "Parent=Task Features" "Priority=Expert" "Type=bool" "Desc=Habilitar una tarea de mover adicional (move2). move2 es en esencia igual a mover. Su finalidad principal es permitir un segundo conjunto de valores de configuración." "Value=false" "Display=Checkbox&&Status:Deprecated"
CustomInfo: ConfigParam "Name=TaskDockForever" "Parent=Task Features" "Priority=Expert" "Type=bool" "Desc=Habilitar una tarea que coloque al robot en posición de atraque para siempre. Esta es la misma funcionalidad proporcionada por el botón de posición de atraque en las aplicaciones del cliente. (Obsoleto. Use TaskForevers en vez de ella)." "Value=false" "Display=Checkbox&&Status:Deprecated"
CustomInfo: ConfigParam "Name=TaskSetMovementParametersTemp" "Parent=Task Features" "Priority=Expert" "Type=bool" "Desc=Habilitar la tarea setMovementParamsTemp para configurar temporalmente los parámetros de movimiento. (Obsoleto. Se prefiere MovementParametersTempTasks. Las dos son compatibles." "Value=false" "Display=Checkbox&&Status:Deprecated"
CustomInfo: ConfigParam "Name=TasksForPIDSettings" "Parent=Task Features" "Priority=Normal" "Type=bool" "Desc=Habilitar las tareas que cambian los ajustes de PID. Si se habilita (verdadero), entonces el parámetro PIDConfig en Configuración del robot debería deshabilitarse. De lo contrario, una cantidad excesiva de paquetes se enviará al robot cuando la configuración se modifique." "Value=false" "Display=Checkbox&&Status:BETA"
CustomInfo: ConfigParam "Name=ApplicationFaultTasks" "Parent=Task Features" "Priority=Normal" "Type=bool" "Desc=Habilitar applicationFaultSet/applicationFaultClear y applicationBlockDrivingSet/applicationBlockDrivingClear como tareas." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=DataLogMakeNewFile" "Parent=Task Features" "Priority=Normal" "Type=bool" "Desc=En el supuesto de que el registro de datos no se haya deshabilitado, esto crea una tarea que elaborará un nuevo registro de datos." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=StayAndGoTasks" "Parent=Task Features" "Priority=Normal" "Type=bool" "Desc=Habilitar «Permanecer» e «Ir» como tareas (como disponibles en la pantalla táctil y ARCL).  Permanecer comienza una nueva espera de un minuto o extiende una espera en curso en un minuto adicional.   Ir cancela cualquier espera en curso y generalmente ocasiona que el robot reanude la ejecución de trabajos de Queuing Manager o a una ruta que «ha permanecido» previamente.  (Nota de aplicación:  Esto se realiza actualmente aumentando de manera artificial el tiempo inactivo del robot a dos minutos)." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=CustomResponses" "Parent=Task Features" "Priority=Normal" "Type=bool" "Desc=Habilita las respuestas personalizadas, que permiten la definición de listas de tareas para diversos eventos. Cuando se habilitan, las respuestas personalizadas se incluyen en la ficha «Especial» en MobilePlanner." "Value=true" "Display=Checkbox"
CustomInfo: ConfigParam "Name=TaskArclSendText" "Parent=Task Features" "Priority=Normal" "Type=bool" "Desc=Habilitar una tarea que envía texto definido por el usuario al servidor de ARCL. (Usar con precaución. (El texto no debe entrar en conflicto con las respuestas/comandos ARCL definidos)." "Value=true" "Display=Checkbox"
CustomInfo: ConfigParam "Name=MovementParametersTempTasks" "Parent=Task Features" "Priority=Normal" "Type=bool" "Desc=Habilitar tareas que permiten cambiar los parámetros del movimiento temporalmente. El cambio persiste durante la duración del objetivo, ruta, etc., actuales." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=MovementParametersTask" "Parent=Task Features" "Priority=Normal" "Type=bool" "Desc=Habilitar una tarea que permita modificar los parámetros del movimiento hasta que se cambian explícitamente." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=MoveProx" "Parent=Task Features" "Priority=Normal" "Type=bool" "Desc=Habilitar la tarea moveProx. Esto es similar a mover, pero también proporciona compatibilidad con los sensores de proximidad. Si se define algún sensor de proximidad, el robot se moverá hasta que uno se active." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=DeltaHeadingProx" "Parent=Task Features" "Priority=Normal" "Type=bool" "Desc=Habilitar la tarea deltaHeadingProx. Esto es similar a deltaHeading, excepto que el robot deja de girar si se activa alguno de los sensores de proximidad. Cuando se habilita, la velocidad de rotación del robot (Configuración del robot > RotVelMax, etc.) debería configurarse en un valor bajo para que el robot pueda parar rápidamente." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=ProxTasks_v2" "Parent=Task Features" "Priority=Expert" "Type=bool" "Desc=Habilitar las tareas moveProx_v2 y deltaHeadingProx_v2, que permiten la comprobación de un sensor de proximidad específico. Estas sustituirán eventualmente las tareas moveProx y deltaHeadingProx." "Value=false" "Display=Checkbox&&Status:Deprecated"
CustomInfo: ConfigParam "Name=Engage" "Parent=Task Features" "Priority=Normal" "Type=bool" "Desc=Habilitar la tarea Alcanzar.  Esto se usa para ejecutar una macro después de llegar a un objetivo, pero no repetir la macro si hay trabajos repetidos en ese objetivo." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=JobTypeCheck" "Parent=Task Features" "Priority=Normal" "Type=bool" "Desc=Habilitar la tarea JobTypeCheck, que permite que se ejecute una macro diferente en función de si el objetivo actual es una recogida, una descarga, o ninguna de ellas." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=RobotSimTypeCheck" "Parent=Task Features" "Priority=Normal" "Type=bool" "Desc=Habilita una tarea RobotSimTypeCheck, que le permite especificar una macro diferente en función de si el robot es real o simulado.  Esto es útil para los mapas de localización y reparación de averías, que incluyen tareas que no se pueden simular." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=TasksForBetterCustomIO" "Parent=Task Features" "Priority=Normal" "Type=bool" "Desc=Habilitar tareas mejoradas para tratar con una E/S personalizada. (TasksForCustomIO ha quedado obsoleta. Use TasksForBetterCustomIO en vez de ella)." "Value=true" "Display=Checkbox"
CustomInfo: ConfigParam "Name=TasksForBetterCustomIOWithFast" "Parent=Task Features" "Priority=Normal" "Type=bool" "Desc=Habilitar tareas de tercera generación para tratar con una E/S personalizada, junto con las versiones «rápidas» correspondientes. (Las versiones «rápidas» aún están en desarrollo y, en general, no deberían utilizarse)." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=TasksForCustomIO" "Parent=Task Features" "Priority=Expert" "Type=bool" "Desc=Habilitar tareas para tratar con una E/S personalizada. (Obsoleto. Use TasksForBetterCustomIO en vez de ella)." "Value=false" "Display=Checkbox&&Status:Deprecated"
CustomInfo: ConfigParam "Name=TaskForevers" "Parent=Task Features" "Priority=Normal" "Type=bool" "Desc=Habilitar las tareas «siempre». Estas cambian el modo de un robot y no regresan a la ubicación de llamada. Esta es una opción avanzada." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=PathPlanningSettingsTempTasks" "Parent=Task Features" "Priority=Normal" "Type=bool" "Desc=Habilitar tareas que permiten cambiar los ajustes de planificación de rutas temporalmente." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=VolumeAdjustmentTempTasks" "Parent=Task Features" "Priority=Normal" "Type=bool" "Desc=Habilita las tareas temporales de VolumeAdjustment para cambiar el volumen de la salida de audio del robot (de manera separada del controlador deslizante externo)" "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=TaskArbitraryServerSend" "Parent=Task Features" "Priority=Normal" "Type=bool" "Desc=Habilitar una tarea que envía el texto a un servidor especificado. (Usar con precaución. Cuando se habilita, el uso inadecuado podría tener potencialmente efectos adversos en una red." "Value=true" "Display=Checkbox"
CustomInfo: ConfigParam "Name=TaskArbitraryServerSendInstant" "Parent=Task Features" "Priority=Normal" "Type=bool" "Desc=Habilita una tarea que envía cadenas de manera instantánea a un servidor arbitrario (piénselo bien antes de habilitar, ya que el uso inadecuado podría causar caos en una red)" "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=TaskEnableMotorsInstant" "Parent=Task Features" "Priority=Expert" "Type=bool" "Desc=Habilitar la tarea enableMotorsInstant. Esto puede usarse para borrar una estop, por ejemplo. (Usar con precaución. Pueden generarse daños o lesiones a causa del uso indebido dado que el robot podría empezar a moverse una vez habilitados los motores. No ejecute la tarea sin la entrada explícita del usuario." "Value=false" "Display=Checkbox&&Status:Deprecated"
CustomInfo: ConfigParam "Name=TaskShutdownRobot" "Parent=Task Features" "Priority=Normal" "Type=bool" "Desc=Habilitar una tarea que apague el robot." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=TaskRestartARAM" "Parent=Task Features" "Priority=Normal" "Type=bool" "Desc=Habilitar una tarea que reinicie ARAM." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=TaskLocalizeAtGoal" "Parent=Task Features" "Priority=Normal" "Type=bool" "Desc=Habilitar la tarea localizeAtGoal. (Usar con precaución. Si se usa de manera incorrecta, esta tarea puede hacer que el robot se extravíe." "Value=true" "Display=Checkbox"
CustomInfo: ConfigParam "Name=TaskQueueDropoff" "Parent=Task Features" "Priority=Normal" "Type=bool" "Desc=Habilita una tarea queueDropoff que pondrá en cola de espera una descarga para ese robot" "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=TaskQueueDropoffRandom" "Parent=Task Features" "Priority=Normal" "Type=bool" "Desc=Habilitar la tarea queueDropoff, que coloca en cola de espera una descarga o un objetivo aleatorio en ese robot (opcionalmente, que coincida con cierto prefijo)." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=GotoStraight" "Parent=Task Features" "Priority=Expert" "Type=bool" "Desc=Habilitar la tarea GotoStraight.  Esta tarea no usa planificación de ruta.  El robot simplemente apunta y conduce hacia la posición objetivo; se para según sea necesario si se encuentra un obstáculo.  Después de llegar a la posición objetivo, el robot gira hacia el rumbo objetivo.  En general, este no es un comportamiento óptimo y ninguno de los otros sistemas lo tratará como un objetivo normal.  (Por ejemplo, las asociaciones de objetivo «antes» y «después» no se ejecutarán).  Esta tarea solo debería usarse en casos limitados." "Value=false" "Display=Checkbox&&Status:Deprecated"
CustomInfo: ConfigParam "Name=TaskFaceClosest" "Parent=Task Features" "Priority=Normal" "Type=bool" "Desc=Habilitar una tarea que rote el robot para encarar el obstáculo más cercano dentro de cierta distancia." "Value=false" "Display=Checkbox&&Status:BETA"
CustomInfo: ConfigParam "Name=TaskCompareNumLights" "Parent=Task Features" "Priority=Normal" "Type=bool" "Desc=Habilitar una tarea que compara el número de luces y modifica su comportamiento de forma correspondiente." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=" "Parent=Task Features" "Priority=Expert" "Type=unknown" "Desc="
CustomInfo: ConfigSection "Name=Teleop Settings"
CustomInfo: ConfigParam "Name=DisableRobotJoystickOverride" "Parent=Teleop Settings" "Priority=Expert" "Type=bool" "Desc=Deshabilitar la capacidad de la palanca de control para anular todo comportamiento (incluido, por ejemplo, atracar)." "Value=false" "Display=Checkbox&&Status:Deprecated"
CustomInfo: ConfigParam "Name=RobotJoystickAdjustCenter" "Parent=Teleop Settings" "Priority=Expert" "Type=bool" "Desc=Habilitar la visualización y ajuste del punto central en la palanca de control." "Value=false" "Display=Checkbox&&Status:Deprecated"
CustomInfo: ConfigParam "Name=RobotTeleopAvoidVirtuals" "Parent=Teleop Settings" "Priority=Expert" "Type=bool" "Desc=Evitar obstáculos que dependen de la ubicación (como áreas prohibidas) durante la teleoperación de la palanca de control. Cuando esto se habilita, el robot también se parará si se extravía durante la teleoperación." "Value=false" "Display=Checkbox"
CustomInfo: ConfigParam "Name=" "Parent=Teleop Settings" "Priority=Expert" "Type=unknown" "Desc="
CustomInfo: ConfigParam "Name=Timeout" "Parent=Teleop Settings" "Priority=Expert" "Type=double" "Desc=Duración en segundos en que el robot continuará moviéndose cuando no se reciben comandos de teleoperación. Se permiten fracciones de segundos. 0 para deshabilitar." "Value=2" "Min=0"
CustomInfo: ConfigParam "Name=Timeout" "Parent=Teleop Settings" "Priority=Expert" "Type=double" "Desc=Duración en segundos en que el robot continuará moviéndose cuando no se reciben comandos de teleoperación. Se permiten fracciones de segundos. 0 para deshabilitar." "Value=2" "Min=0"
CustomInfo: ConfigParam "Name=FullThrottleForwards" "Parent=Teleop Settings" "Priority=Expert" "Type=double" "Desc=Velocidad máxima hacia adelante (en mm/s) durante el modo de teleoperación. 0 significa el valor de TransVelMax del robot." "Value=0" "Min=0"
CustomInfo: ConfigParam "Name=FullThrottleForwards" "Parent=Teleop Settings" "Priority=Expert" "Type=double" "Desc=Velocidad máxima hacia adelante (en mm/s) durante el modo de teleoperación. 0 significa el valor de TransVelMax del robot." "Value=0" "Min=0"
CustomInfo: ConfigParam "Name=FullThrottleBackwards" "Parent=Teleop Settings" "Priority=Expert" "Type=double" "Desc=Velocidad máxima hacia atrás (en mm/s) durante el modo de teleoperación. 0 significa 1/4del valor de TransVelMax del robot." "Value=0" "Min=0"
CustomInfo: ConfigParam "Name=FullThrottleBackwards" "Parent=Teleop Settings" "Priority=Expert" "Type=double" "Desc=Velocidad máxima hacia atrás (en mm/s) durante el modo de teleoperación. 0 significa 1/4del valor de TransVelMax del robot." "Value=0" "Min=0"
CustomInfo: ConfigParam "Name=RotAtFullForwards" "Parent=Teleop Settings" "Priority=Expert" "Type=double" "Desc=Velocidad máxima de rotación (en grados/s) durante el movimiento a FullThrottleForwards. 0 significa 1/2 del valor de RotVelMax del robot." "Value=25" "Min=0"
CustomInfo: ConfigParam "Name=RotAtFullForwards" "Parent=Teleop Settings" "Priority=Expert" "Type=double" "Desc=Velocidad máxima de rotación (en grados/s) durante el movimiento a FullThrottleForwards. 0 significa 1/2 del valor de RotVelMax del robot." "Value=25" "Min=0"
CustomInfo: ConfigParam "Name=RotAtFullBackwards" "Parent=Teleop Settings" "Priority=Expert" "Type=double" "Desc=Velocidad máxima de rotación (en grados/s) durante el movimiento a FullThrottleBackwards. 0 significa 1/2 del valor de RotVelMax del robot." "Value=25" "Min=0"
