CustomInfo: ConfigSection "Name=Triangle Drive To"
CustomInfo: ConfigParam "Name=FinalDistFromVertex" "Parent=Triangle Drive To" "Priority=Expert" "Type=double" "Desc=La distancia desde el vértice del punto de parada final (según el centro del robot); 0 significa ir hasta un bache o una parada." "Value=500" "Max=2000"
CustomInfo: ConfigParam "Name=ApproachDistFromVertex" "Parent=Triangle Drive To" "Priority=Expert" "Type=double" "Desc=La distancia desde el vértice hasta el punto de aproximación (para el centro del robot)." "Value=750" "Max=2500"
CustomInfo: ConfigParam "Name=FailTime" "Parent=Triangle Drive To" "Priority=Expert" "Type=int" "Desc=Si se toma más segundos que esto, la tarea fallará." "Value=45" "Min=0"
CustomInfo: ConfigParam "Name=TriangleDriveSpeed" "Parent=Triangle Drive To" "Priority=Expert" "Type=double" "Desc=Velocidad a la cual conducir para la aproximación" "Value=100" "Max=500"
CustomInfo: ConfigParam "Name=TriangleDriveTolerance" "Parent=Triangle Drive To" "Priority=Expert" "Type=double" "Desc=Cuánto intentar acercarse al punto" "Value=25" "Max=200"
CustomInfo: ConfigParam "Name=Line1Length" "Parent=Triangle Drive To" "Priority=Expert" "Type=double" "Desc=Longitud de la primera línea del objetivo triangular; 0 significa que cualquier longitud es adecuada" "Value=154" "Max=1000"
CustomInfo: ConfigParam "Name=AngleBetweenLines" "Parent=Triangle Drive To" "Priority=Expert" "Type=double" "Desc=El ángulo entre las dos líneas; 0 significa que cualquier ángulo es adecuado" "Value=-146" "Max=180"
CustomInfo: ConfigParam "Name=Line2Length" "Parent=Triangle Drive To" "Priority=Expert" "Type=double" "Desc=Longitud de la segunda línea del objetivo triangular; 0 significa que cualquier longitud es adecuada" "Value=154" "Max=1000"
CustomInfo: ConfigParam "Name=MaxDistBetweenLinePoints" "Parent=Triangle Drive To" "Priority=Expert" "Type=int" "Desc=Distancia máxima entre los puntos que se convierten en líneas, este es un parámetro que se utiliza para tratar de deshacerse de los puntos donde un láser vio parte de la marca guía y parte del fondo.  0 significa que no usará esta función (mm)" "Value=0" "Min=0"
CustomInfo: ConfigParam "Name=MaxLateralDist" "Parent=Triangle Drive To" "Priority=Expert" "Type=int" "Desc=El valor máximo de cuánto a la izquierda o a la derecha el robot buscará un vértice.  (Técnicamente, la máxima distancia entre el centro del robot y una línea imaginaria que sale desde el vértice).  Cualquier vértice mayor a esa cantidad se ignorará por completo.  0 significa que no usará esta función (mm)" "Value=0" "Min=0"
CustomInfo: ConfigParam "Name=MaxAngleMisalignment" "Parent=Triangle Drive To" "Priority=Expert" "Type=int" "Desc=El máximo de cuánto el ángulo del robot y el ángulo de la línea del vértice pueden estar apartados entre sí.  Cualquier línea de vértice mayor a esa cantidad se ignorará por completo.  0 significa que no usará esta función (grados)" "Value=0" "Min=0"
CustomInfo: ConfigParam "Name=TriangleFrontClearance" "Parent=Triangle Drive To" "Priority=Expert" "Type=double" "Desc=Si algún obstáculo entra dentro de esta distancia del robot mientras se conduce al objetivo triangular, el robot se parará; esto debería ser lo suficientemente grande para que el robot pueda planear una ruta para alejarse" "Value=100"
CustomInfo: ConfigParam "Name=TriangleSideClearance" "Parent=Triangle Drive To" "Priority=Expert" "Type=double" "Desc=Si algún obstáculo entra dentro de esta distancia del robot mientras se conduce al objetivo triangular, el robot se parará; esto debería ser lo suficientemente grande para que el robot pueda planear una ruta para alejarse" "Value=100"
CustomInfo: ConfigParam "Name=AvoidLocationDependentObstacles" "Parent=Triangle Drive To" "Priority=Expert" "Type=bool" "Desc=Cuando está habilitado (verdadero), el robot evita los obstáculos que dependen de la ubicación, como líneas prohibidas y otros robots. Si esta opción está deshabilitada, deben usarse protecciones físicas para contener al robot." "Value=true"
CustomInfo: ConfigParam "Name=TriangleAdjustVertex" "Parent=Triangle Drive To" "Priority=Expert" "Type=bool" "Desc=Usar o no un cálculo alterno para el vértice" "Value=false"
CustomInfo: ConfigParam "Name=TriangleGotoVertex" "Parent=Triangle Drive To" "Priority=Expert" "Type=bool" "Desc=Verdadero para ir hacia el vértice en vez de hacia el punto frente a él." "Value=false"
CustomInfo: ConfigParam "Name=TriangleIgnoreDist" "Parent=Triangle Drive To" "Priority=Expert" "Type=double" "Desc=El valor por defecto anterior era 0 para GotoVertex verdadero y 250 para GotoVertex falso.  Cuando el robot está dentro de este número de milímetros de su punto final, comenzará a ignorar el objetivo triangular y simplemente irá con base en la última lectura (ya que a medida que se acerca, a veces se pierde la marca guía; esto probablemente no sea necesario con marcas guía de un color distinto al negro)" "Value=250"
CustomInfo: ConfigParam "Name=TriangleBackDist" "Parent=Triangle Drive To" "Priority=Expert" "Type=int" "Desc=Después de alcanzado el punto del objetivo triangular, el robot retrocederá esta distancia" "Value=0" "Max=0"
CustomInfo: ConfigParam "Name=TriangleLogMore" "Parent=Triangle Drive To" "Priority=Expert" "Type=bool" "Desc=Registra más información sobre la conducción hacia el objetivo triangular" "Value=false"
CustomInfo: ConfigParam "Name=TriangleTransVelMax" "Parent=Triangle Drive To" "Priority=Expert" "Type=double" "Desc=Velocidad de traslación máxima hacia adelante (0 significa uso del valor por defecto)" "Value=0" "Min=0"
CustomInfo: ConfigParam "Name=TriangleTransNegVelMax" "Parent=Triangle Drive To" "Priority=Expert" "Type=double" "Desc=Velocidad de traslación máxima hacia atrás (0 significa uso del valor por defecto)" "Value=0" "Min=0"
CustomInfo: ConfigParam "Name=TriangleTransAccel" "Parent=Triangle Drive To" "Priority=Expert" "Type=double" "Desc=Aceleración de traslación (0 significa uso del valor por defecto)" "Value=0" "Min=0"
CustomInfo: ConfigParam "Name=TriangleTransDecel" "Parent=Triangle Drive To" "Priority=Expert" "Type=double" "Desc=Desaceleración de traslación (0 significa uso del valor por defecto)" "Value=0" "Min=0"
CustomInfo: ConfigParam "Name=TriangleRotVelMax" "Parent=Triangle Drive To" "Priority=Expert" "Type=double" "Desc=Velocidad de rotación máxima (0 significa uso del valor por defecto)" "Value=0" "Min=0"
CustomInfo: ConfigParam "Name=TriangleRotAccel" "Parent=Triangle Drive To" "Priority=Expert" "Type=double" "Desc=Aceleración de rotación (0 significa uso del valor por defecto)" "Value=0" "Min=0"
CustomInfo: ConfigParam "Name=TriangleRotDecel" "Parent=Triangle Drive To" "Priority=Expert" "Type=double" "Desc=Desaceleración de rotación (0 significa uso del valor por defecto)" "Value=0" "Min=0"
CustomInfo: ConfigParam "Name=UseQuickStop" "Parent=Triangle Drive To" "Priority=Expert" "Type=bool" "Desc=Si debemos o no usar una parada rápida cuando la proximidad o la entrada se activa (esto es como una estop, pero no se engancha, y usará frenos en una plataforma que los tenga)." "Value=false"
