TaskInfo: TaskDesc "Name=customOutputOff" "Desc=Desactiva la salida personalizada especificada." "Class=Instant"
TaskInfo: ArgDesc "Name=output" "Parent=customOutputOff" "Type=string" "Priority=Important" "Desc=Salida personalizada que se apagará." "Value=" "Display=DigitalIO:customOutputs|Optional" "Label=output"
TaskInfo: TaskDesc "Name=customOutputOn" "Desc=Activa la salida personalizada especificada." "Class=Instant"
TaskInfo: ArgDesc "Name=output" "Parent=customOutputOn" "Type=string" "Priority=Important" "Desc=Salida personalizada que se encenderá." "Value=" "Display=DigitalIO:customOutputs|Optional" "Label=output"
TaskInfo: TaskDesc "Name=deltaHeading" "Desc=Cambia el rumbo por el valor relativo especificado." "Class=Movement|Heading"
TaskInfo: ArgDesc "Name=delta heading" "Parent=deltaHeading" "Type=int" "Priority=Important" "Desc=Cantidad (en grados) que gira el robot. Use valores positivos para girar el robot hacia la izquierda/sentido antihorario; valores negativos para girarlo a la derecha/sentido horario. Tenga en cuenta que si el valor absoluto excede 360, el robot hará por lo menos una rotación completa." "Value=0" "Label=Cambio de rumbo"
TaskInfo: ArgDesc "Name=rotVelMax" "Parent=deltaHeading" "Type=int" "Priority=Detailed" "Desc=Velocidad de rotación máxima (en grados/s) al girar. 0 significa que se usa el valor por defecto." "Value=0" "Min=0" "Label=rotVelMax"
TaskInfo: ArgDesc "Name=rotAccel" "Parent=deltaHeading" "Type=int" "Priority=Detailed" "Desc=Aceleración de rotación (en grados/s/s) al girar. 0 significa que se usa el valor por defecto." "Value=0" "Min=0" "Label=rotAccel"
TaskInfo: ArgDesc "Name=rotDecel" "Parent=deltaHeading" "Type=int" "Priority=Detailed" "Desc=Desaceleración de rotación (en grados/s/s) al girar. 0 significa que se usa el valor por defecto." "Value=0" "Min=0" "Label=rotDecel"
TaskInfo: ArgDesc "Name=time until fail" "Parent=deltaHeading" "Type=int" "Priority=Detailed" "Desc=Tiempo de espera (en segundos) si no es posible girar antes de declarar que la tarea ha fallado." "Value=30" "Min=0" "Label=tiempo antes de fallo"
TaskInfo: ArgDesc "Name=minimum time" "Parent=deltaHeading" "Type=int" "Priority=Detailed" "Desc=Duración mínima (en segundos) para esta tarea. Si el robot alcanza su destino en menos tiempo, la tarea espera el recordatorio de la duración. 0 significa que la tarea debería completarse en cuanto el robot llegue a su rumbo de destino." "Value=0" "Min=0" "Label=tiempo mínimo"
TaskInfo: ArgDesc "Name=use localization" "Parent=deltaHeading" "Type=bool" "Priority=Detailed" "Desc=Verdadero para usar la localización mientras gira. Falso para confiar únicamente en la odometría." "Value=true" "Label=Usar localización"
TaskInfo: ArgDesc "Name=checkRadius" "Parent=deltaHeading" "Type=bool" "Priority=Detailed" "Desc=Para la rotación del robot cuando hay un objeto dentro de un radio definido por el usuario." "Value=false" "Label=checkRadius"
TaskInfo: ArgDesc "Name=radiusAdjustment" "Parent=deltaHeading" "Type=int" "Priority=Detailed" "Desc=El radio adicional (mm) más allá del radio del robot para detectar obstáculos al rotar." "Value=0" "Label=radiusAdjustment"
TaskInfo: TaskDesc "Name=display" "Desc=Sends a message to the Operator Panel screen." "Class=Instant"
TaskInfo: ArgDesc "Name=Message" "Parent=display" "Type=string" "Priority=Important" "Desc=The message to display on the Operator Panel screen. Only ASCII characters are supported. New line characters (\n) are allowed. (Special Codes: $g=goal name. Current robot position $X (x in mm) $Y (y in mm) $T (heading in degrees, -180 to 180). Time in GMT: $y=current year, $m=month, $d=day, $H=hour, $M=minute, $S=second.)" "Value=" "Label=Message"
TaskInfo: GoalTaskDesc "Name=goto" "Desc=Conduce hacia un objetivo especificado." "Class=Movement" "Label=goto (un destino)"
TaskInfo: ArgDesc "Name=goal to go to" "Parent=goto" "Type=string" "Priority=Normal" "Desc=Nombre del objetivo de destino." "Value=" "Display=MapItem:Goal|Parent|OptionalAndEditable" "Label=objetivo al que dirigirse"
TaskInfo: TaskDesc "Name=gotoPoint" "Desc=Conduce hacia un punto especificado." "Class=Movement"
TaskInfo: ArgDesc "Name=x" "Parent=gotoPoint" "Type=int" "Priority=Important" "Desc=Coordenada X (en mm) en el destino." "Value=0" "Label=x"
TaskInfo: ArgDesc "Name=y" "Parent=gotoPoint" "Type=int" "Priority=Important" "Desc=Coordenada Y (en mm) en el destino." "Value=0" "Label=y"
TaskInfo: ArgDesc "Name=heading" "Parent=gotoPoint" "Type=int" "Priority=Normal" "Desc=Rumbo (en grados) que se debe tener una vez alcanzado el destino." "Value=0" "Label=rumbo"
TaskInfo: TaskDesc "Name=gotoRandom" "Desc=Conduce hacia un objetivo aleatorio, que puede restringirse opcionalmente al coincidir con un prefijo del nombre." "Class=Movement"
TaskInfo: ArgDesc "Name=prefix" "Parent=gotoRandom" "Type=string" "Priority=Normal" "Desc=Si se especifica un prefijo, solo se seleccionan los nombres de objetivo que comienzan con ese prefijo. Si está vacío, se selecciona cualquier objetivo Los comodines no son compatibles." "Value=" "Label=prefix"
TaskInfo: TaskDesc "Name=laserCheckBox" "Desc=Espera a que algo se introduzca en el área rectangular que rodea el robot. Pueden ejecutarse macros después de la detección o de que se agote el tiempo de espera." "Class=Monitor"
TaskInfo: ArgDesc "Name=width" "Parent=laserCheckBox" "Type=int" "Priority=Important" "Desc=Ancho (en mm) del área que se revisará, a partir del centro del robot." "Value=2000" "Min=100" "Label=ancho"
TaskInfo: ArgDesc "Name=length" "Parent=laserCheckBox" "Type=int" "Priority=Important" "Desc=Longitud (en mm) del área que se revisará, a partir del centro del robot." "Value=2000" "Min=100" "Label=longitud"
TaskInfo: ArgDesc "Name=triggerMacro" "Parent=laserCheckBox" "Type=string" "Priority=Normal" "Desc=Macro que se invocará cuando se detecte algo en el área. Opcional." "Value=" "Display=Macro" "Label=triggerMacro"
TaskInfo: ArgDesc "Name=timeout" "Parent=laserCheckBox" "Type=int" "Priority=Normal" "Desc=Duración máxima (en segundos) de la espera para detectar algo. 0 significa siempre." "Value=0" "Min=0" "Label=tiempo de espera agotado"
TaskInfo: ArgDesc "Name=timeoutMacro" "Parent=laserCheckBox" "Type=string" "Priority=Normal" "Desc=Macro que se invocará si no se detecta nada en el área durante el tiempo de espera especificado. Opcional." "Value=" "Display=Macro" "Label=timeoutMacro"
TaskInfo: TaskDesc "Name=laserCheckEmptyBox" "Desc=Espera a que el área rectangular que rodea el robot esté vacía. Pueden ejecutarse macros después de la detección o de que se agote el tiempo de espera." "Class=Monitor"
TaskInfo: ArgDesc "Name=width" "Parent=laserCheckEmptyBox" "Type=int" "Priority=Important" "Desc=Ancho (en mm) del área que se revisará, a partir del centro del robot." "Value=2000" "Min=100" "Label=ancho"
TaskInfo: ArgDesc "Name=length" "Parent=laserCheckEmptyBox" "Type=int" "Priority=Important" "Desc=Longitud (en mm) del área que se revisará, a partir del centro del robot." "Value=2000" "Min=100" "Label=longitud"
TaskInfo: ArgDesc "Name=triggerMacro" "Parent=laserCheckEmptyBox" "Type=string" "Priority=Normal" "Desc=Macro que se invocará cuando el área esté vacía. Opcional." "Value=" "Display=Macro" "Label=triggerMacro"
TaskInfo: ArgDesc "Name=timeout" "Parent=laserCheckEmptyBox" "Type=int" "Priority=Normal" "Desc=Duración máxima (en segundos) de la espera para que el área se vacíe. 0 significa siempre." "Value=0" "Min=0" "Label=tiempo de espera agotado"
TaskInfo: ArgDesc "Name=timeoutMacro" "Parent=laserCheckEmptyBox" "Type=string" "Priority=Normal" "Desc=Macro que se invocará si el área no se vacía durante el tiempo de espera especificado. Opcional." "Value=" "Display=Macro" "Label=timeoutMacro"
TaskInfo: TaskDesc "Name=laserCheckPolar" "Desc=Espera a que algo se introduzca en el área angular (es decir, en forma de sección) y rodee el robot. Pueden ejecutarse macros después de la detección o de que se agote el tiempo de espera." "Class=Monitor"
TaskInfo: ArgDesc "Name=start angle" "Parent=laserCheckPolar" "Type=int" "Priority=Important" "Desc=Ángulo de inicio (en grados) del área que se revisará. Esto debería ser menor que el ángulo final. (De lo contrario, la sección está invertida)." "Value=-45" "Min=-180" "Max=180" "Label=ángulo de inicio"
TaskInfo: ArgDesc "Name=end angle" "Parent=laserCheckPolar" "Type=int" "Priority=Important" "Desc=Ángulo final (en grados) del área que se revisará. Esto debería ser mayor que el ángulo de inicio. (De lo contrario, la sección está invertida)." "Value=45" "Min=-180" "Max=180" "Label=ángulo final"
TaskInfo: ArgDesc "Name=dist" "Parent=laserCheckPolar" "Type=int" "Priority=Important" "Desc=Longitud (en mm) del área que se extiende en frente del robot." "Value=1000" "Min=0" "Label=dist"
TaskInfo: ArgDesc "Name=triggerMacro" "Parent=laserCheckPolar" "Type=string" "Priority=Normal" "Desc=Macro que se invocará cuando se detecte algo en el área. Opcional." "Value=" "Display=Macro" "Label=triggerMacro"
TaskInfo: ArgDesc "Name=timeout" "Parent=laserCheckPolar" "Type=int" "Priority=Normal" "Desc=Duración máxima (en segundos) de la espera para detectar algo. 0 significa siempre." "Value=0" "Min=0" "Label=tiempo de espera agotado"
TaskInfo: ArgDesc "Name=timeoutMacro" "Parent=laserCheckPolar" "Type=string" "Priority=Normal" "Desc=Macro que se invocará si no se detecta nada en el área durante el tiempo de espera especificado. Opcional." "Value=" "Display=Macro" "Label=timeoutMacro"
TaskInfo: TaskDesc "Name=laserGreetBox" "Desc=Espera que algo entre a la caja, dice algo y luego intenta conducir hacia ello" "Class=Movement|RobotAudio"
TaskInfo: ArgDesc "Name=width" "Parent=laserGreetBox" "Type=int" "Priority=Important" "Desc=El ancho de la casilla que se comprobará, medido en mm, centrado en el medio del robot" "Value=2000" "Min=100" "Label=ancho"
TaskInfo: ArgDesc "Name=length" "Parent=laserGreetBox" "Type=int" "Priority=Important" "Desc=La longitud de la casilla que se comprobará, medida en mm, centrada en el medio del robot" "Value=2000" "Min=100" "Label=longitud"
TaskInfo: ArgDesc "Name=greeting speech" "Parent=laserGreetBox" "Type=string" "Priority=Normal" "Desc=Lo que se dice cuando alguien entra en la caja, antes de conducir hacia él o ella. (Códigos especiales: $g=nombre del objetivo. Posición actual del robot $X (x en mm) $Y (y en mm) $T (rumbo en grados, -180 to 180). Hora en GMT: $y=año actual, $m=mes, $d=día, $H=hora, $M=minuto, $S=segundo." "Value=" "Label=Voz de saludo"
TaskInfo: ArgDesc "Name=speed" "Parent=laserGreetBox" "Type=int" "Priority=Normal" "Desc=La velocidad en mm/s a la que el robot debería moverse" "Value=400" "Min=0" "Label=velocidad"
TaskInfo: ArgDesc "Name=front clearance" "Parent=laserGreetBox" "Type=int" "Priority=Detailed" "Desc=La distancia en mm a la que el robot debería detenerse cuando hay obstáculos enfrente" "Value=200" "Label=espacio libre delantero"
TaskInfo: ArgDesc "Name=front padding at stopped" "Parent=laserGreetBox" "Type=int" "Priority=Detailed" "Desc=El espacio libre adicional a velocidad 0" "Value=200" "Label=espacio libre adicional delantero al parar"
TaskInfo: ArgDesc "Name=front padding at speed" "Parent=laserGreetBox" "Type=int" "Priority=Detailed" "Desc=El espacio libre adicional al marchar a la velocidad de parámetro" "Value=400" "Label=espacio libre adicional delantero en marcha"
TaskInfo: ArgDesc "Name=max padding deceleration" "Parent=laserGreetBox" "Type=int" "Priority=Detailed" "Desc=La desaceleración máxima mientras aún se está en el espacio libre adicional (hará una estop si algo atraviesa el espacio libre adicional)" "Value=600" "Label=desaceleración máxima del espacio libre adicional"
TaskInfo: ArgDesc "Name=side clearance" "Parent=laserGreetBox" "Type=int" "Priority=Detailed" "Desc=La distancia en mm a la que el robot debería detenerse cuando hay obstáculos al lado" "Value=50" "Label=espacio libre lateral"
TaskInfo: ArgDesc "Name=transAccel" "Parent=laserGreetBox" "Type=int" "Priority=Detailed" "Desc=La aceleración de traslación que se usará, 0 significa usar aquella por defecto del robot" "Value=0" "Min=0" "Label=transAccel"
TaskInfo: ArgDesc "Name=transDecel" "Parent=laserGreetBox" "Type=int" "Priority=Detailed" "Desc=La desaceleración de traslación que se usará, 0 significa usar el valor por defecto del robot" "Value=0" "Min=0" "Label=transDecel"
TaskInfo: ArgDesc "Name=rotVelMax" "Parent=laserGreetBox" "Type=int" "Priority=Detailed" "Desc=La rotVelMax que se usará, 0 significa usar el valor por defecto del robot" "Value=0" "Min=0" "Label=rotVelMax"
TaskInfo: ArgDesc "Name=rotAccel" "Parent=laserGreetBox" "Type=int" "Priority=Detailed" "Desc=La aceleración de rotación que se usará, 0 significa usar el valor por defecto del robot" "Value=0" "Min=0" "Label=rotAccel"
TaskInfo: ArgDesc "Name=rotDecel" "Parent=laserGreetBox" "Type=int" "Priority=Detailed" "Desc=La desaceleración de rotación que se usará, 0 significa usar el valor por defecto del robot" "Value=0" "Min=0" "Label=rotDecel"
TaskInfo: TaskDesc "Name=localizeAtGoal" "Desc=<p><blockquote><b><font color=#A91B16>Usar con precaución. Esta tarea puede hacer que el robot se extravíe.  <nobr> No use la tarea sin la entrada explícita del usuario.</nobr></font></b></blockquote></p><p>Se localiza en un objetivo especificado.</p>" "Class=Localize|Instant"
TaskInfo: ArgDesc "Name=goal to localize at" "Parent=localizeAtGoal" "Type=string" "Priority=Important" "Desc=Nombre del objetivo en el que localizarse." "Value=" "Display=MapItem:Goal|SubtypeAndParent|Required" "Label=objetivo en el cual localizarse"
TaskInfo: ArgDesc "Name=xySpread" "Parent=localizeAtGoal" "Type=double" "Priority=Normal" "Desc=Distancia (en mm) para extender la localización. 0 significa que no se extiende. -1 significa que se usa la extensión por defecto." "Value=-1" "Label=xySpread"
TaskInfo: ArgDesc "Name=angleSpread" "Parent=localizeAtGoal" "Type=double" "Priority=Normal" "Desc=Ángulo (en grados) para extender la localización. 0 significa que no se extiende. -1 significa que se usa la extensión por defecto." "Value=-1" "Label=angleSpread"
TaskInfo: TaskDesc "Name=macroRepeat" "Desc=Invoca repetidamente una macro el número especificado de veces o hasta que la macro falla."
TaskInfo: ArgDesc "Name=macro" "Parent=macroRepeat" "Type=string" "Priority=Important" "Desc=Nombre de la macro que se invocará." "Value=" "Display=Macro" "Label=macro"
TaskInfo: ArgDesc "Name=repeatTimes" "Parent=macroRepeat" "Type=int" "Priority=Normal" "Desc=Número de llamadas a la macro. -1 significa repetir para siempre o hasta que la macro falle." "Value=-1" "Min=-1" "Label=repeatTimes"
TaskInfo: TaskDesc "Name=makeClientsBeep" "Desc=Solicita que las aplicaciones del cliente emitan un pitido. (Las aplicaciones del cliente incluyen MobilePlanner y MobileEyes).  El audio debe estar configurado adecuadamente en el cliente." "Class=ClientAudio|Instant"
TaskInfo: TaskDesc "Name=move" "Desc=Se mueve hacia adelante la distancia especificada, a menos que se encuentren obstáculos." "Class=Movement" "Label=mover"
TaskInfo: ArgDesc "Name=distance" "Parent=move" "Type=int" "Priority=Important" "Desc=Distancia (en mm) para moverse hacia adelante desde la ubicación actual." "Value=1000" "Label=distancia"
TaskInfo: ArgDesc "Name=speed" "Parent=move" "Type=int" "Priority=Normal" "Desc=Velocidad a la que se realiza el movimiento (en mm/segundos)." "Value=400" "Min=0" "Label=velocidad"
TaskInfo: ArgDesc "Name=front clearance" "Parent=move" "Type=int" "Priority=Detailed" "Desc=Distancia (en mm) que se mantiene entre la parte delantera del robot y cualquier obstáculo." "Value=200" "Label=espacio libre delantero"
TaskInfo: ArgDesc "Name=side clearance" "Parent=move" "Type=int" "Priority=Detailed" "Desc=Distancia (en mm) que se mantiene entre la parte lateral del robot y cualquier obstáculo." "Value=50" "Label=espacio libre lateral"
TaskInfo: ArgDesc "Name=time until fail" "Parent=move" "Type=int" "Priority=Detailed" "Desc=Tiempo (en segundos) que se espera para que desparezca un obstáculo antes de declarar que el movimiento ha fallado." "Value=30" "Min=0" "Label=tiempo antes de fallo"
TaskInfo: ArgDesc "Name=transAccel" "Parent=move" "Type=int" "Priority=Detailed" "Desc=Aceleración (en mm/s/s) para el movimiento. 0 significa que se usa la aceleración por defecto del robot." "Value=0" "Min=0" "Label=transAccel"
TaskInfo: ArgDesc "Name=transDecel" "Parent=move" "Type=int" "Priority=Detailed" "Desc=Desaceleración (en mm/s/s) para el movimiento. 0 significa que se usa la aceleración por defecto del robot." "Value=0" "Min=0" "Label=transDecel"
TaskInfo: ArgDesc "Name=minimum time" "Parent=move" "Type=int" "Priority=Detailed" "Desc=Duración mínima (en segundos) para esta tarea. Si el robot alcanza el destino en menos tiempo, la tarea espera el recordatorio de la duración. 0 significa que la tarea debería haberse completado cuando el robot llegue a su destino." "Value=0" "Min=0" "Label=tiempo mínimo"
TaskInfo: ArgDesc "Name=AvoidLocationDependentObstacles" "Parent=move" "Type=bool" "Priority=Detailed" "Desc=Cuando está habilitado (verdadero), el robot evita los obstáculos que dependen de la ubicación, como líneas prohibidas y otros robots. Si esta opción está deshabilitada, deben usarse protecciones físicas para contener al robot." "Value=true" "Label=AvoidLocationDependentObstacles"
TaskInfo: ArgDesc "Name=always succeed" "Parent=move" "Type=bool" "Priority=Detailed" "Desc=Retorno correcto sin importar cuál ha sido la distancia del movimiento. Cuando está habilitado, las tareas informarán que se realizaron correctamente aunque no se haya alcanzado el destino. Cuando está deshabilitado, la tarea falla si el destino no se alcanza." "Value=false" "Label=éxito siempre"
TaskInfo: ArgDesc "Name=finish if stopped" "Parent=move" "Type=bool" "Priority=Detailed" "Desc=Terminar la tarea si el robot no puede moverse después de los dos primeros segundos. Cuando está habilitado, la tarea termina tan pronto como el robot ya no puede moverse. Cuando está deshabilitado, el robot debe encontrarse bloqueado durante el «tiempo antes del fallo» especificado para que la tarea termine." "Value=true" "Label=terminar si está parado"
TaskInfo: TaskDesc "Name=Move: Path" "Desc=Movimiento AMR basado en el mapa" "Class=Movement" "Label=Mover: Ruta"
TaskInfo: ArgDesc "Name=Goal" "Parent=Move: Path" "Type=string" "Priority=Important" "Desc=Especifica el Objetivo según el Mapa al que se quiere navegar." "Value=" "Display=MapItem:Goal|Parent|OptionalAndEditable" "Label=Objetivo"
TaskInfo: ArgDesc "Name=MotionMode" "Parent=Move: Path" "Type=string" "Priority=Important" "Desc=Especifica el tipo de movimiento utilizado durante la ejecución de la tarea." "Value=Default" "Display=Choices:Default;;Dynamic;;AGV;;Straight" "Label=Modo de movimiento"
TaskInfo: ArgDesc "Name=ObstacleMode" "Parent=Move: Path" "Type=string" "Priority=Normal" "Desc=Especifica la manera en que se gestionan los obstáculos durante la ejecución de la tarea" "Value=None" "Display=Choices:None;;Wait&&Visible:MotionMode!=Default" "Label=Modo obstáculo"
TaskInfo: ArgDesc "Name=Timeout" "Parent=Move: Path" "Type=int" "Priority=Normal" "Desc=Tiempo transcurrido en segundos desde que el AMR se detuvo por un obstáculo antes de que la Tarea falle." "Value=400" "Min=1" "Max=6000" "Display=Visible:ObstacleMode!=None&&Visible:MotionMode!=Default" "Label=Tiempo de espera"
TaskInfo: ArgDesc "Name=SmoothingMode" "Parent=Move: Path" "Type=string" "Priority=Normal" "Desc=Especifica el tipo de algoritmo de suavizado utilizado en la ruta del AMR base." "Value=Fixed" "Display=Choices:Fixed;;PreferredLine&&Visible:MotionMode!=Straight&&Visible:MotionMode!=Default" "Label=Modo de suavizado"
TaskInfo: ArgDesc "Name=SmoothingPercentage" "Parent=Move: Path" "Type=double" "Priority=Normal" "Desc=Especifica la cantidad escalada de suavizado utilizada junto con el algoritmo de suavizado. 100 equivale al máximo suavizado." "Value=75" "Min=1" "Max=100" "Display=Visible:MotionMode!=Straight&&Visible:MotionMode!=Default" "Label=Porcentaje de suavizado"
TaskInfo: ArgDesc "Name=ReplanningMode" "Parent=Move: Path" "Type=string" "Priority=Normal" "Desc=Especifica el lado del modo de línea del algoritmo de replanificación." "Value=Normal" "Display=Choices:Normal;;PreferLeft;;PreferRight&&Visible:MotionMode=Dynamic&&Visible:MotionMode!=Default" "Label=Modo de replanificación"
TaskInfo: ArgDesc "Name=LateralReplanningLimit" "Parent=Move: Path" "Type=double" "Priority=Detailed" "Desc=Especifica en mm la distancia lateral máxima que el AMR podría desviarse de su ruta base durante un evento de replanificación." "Value=2500" "Min=50" "Max=3000" "Display=Visible:MotionMode=Dynamic&&Visible:MotionMode!=Default" "Label=Límite de replanificación lateral"
TaskInfo: ArgDesc "Name=ReplanningPreference" "Parent=Move: Path" "Type=double" "Priority=Detailed" "Desc=" "Value=300" "Min=50" "Max=3000" "Display=Visible:False&&Visible:MotionMode!=Default" "Label=ReplanningPreference"
TaskInfo: ArgDesc "Name=ReplanningFreeSpace" "Parent=Move: Path" "Type=double" "Priority=Detailed" "Desc=Especifica la distancia que se debe mantener con respecto a los obstáculos (en mm)." "Value=400" "Min=50" "Max=1000" "Display=Visible:MotionMode=Dynamic&&Visible:MotionMode!=Default" "Label=Replanificación de espacio libre"
TaskInfo: ArgDesc "Name=ReplanningTriggerDistance" "Parent=Move: Path" "Type=double" "Priority=Detailed" "Desc=" "Value=150" "Min=100" "Max=1000" "Display=Visible:False&&Visible:MotionMode!=Default" "Label=ReplanningTriggerDistance"
TaskInfo: ArgDesc "Name=ReplanningTriggerTime" "Parent=Move: Path" "Type=double" "Priority=Detailed" "Desc=Especifica el tiempo de la activación de la replanificación de un evento en segundos. Se mide como el tiempo transcurrido desde que el AMR se detiene por completo." "Value=1" "Min=0.5" "Max=300" "Display=Visible:MotionMode=Dynamic&&Visible:MotionMode!=Default" "Label=Tiempo de activación de replanificación"
TaskInfo: ArgDesc "Name=SeamlessMotionMode" "Parent=Move: Path" "Type=string" "Priority=Normal" "Desc=Optimiza el movimiento cuando es posible para reducir las interrupciones innecesarias en la trayectoria del AMR. Necesita la Licencia de optimización de tiempos de ciclo para activarse." "Value=None" "Display=Choices:None;;Queuing&&Visible:MotionMode!=Default" "Label=SeamlessMotionMode"
TaskInfo: ArgDesc "Name=AllowReverseMotion" "Parent=Move: Path" "Type=bool" "Priority=Detailed" "Desc=Especifica si se permite el Movimiento inverso cuando sea posible para cualquier parte del segmento de movimiento." "Value=false" "Display=Checkbox&&&&Visible:MotionMode!=Default" "Label=Permitir Movimiento inverso"
TaskInfo: ArgDesc "Name=AllowGlobalReplanning" "Parent=Move: Path" "Type=bool" "Priority=Detailed" "Desc=" "Value=false" "Display=Checkbox&&Visible:False&&Visible:MotionMode!=Default" "Label=AllowGlobalReplanning"
TaskInfo: ArgDesc "Name=PositionTolerance" "Parent=Move: Path" "Type=double" "Priority=Normal" "Desc=Máxima tolerancia permitida en mm entre la posición final del AMR y la posición final deseada." "Value=200" "Min=100" "Max=4000" "Display=Visible:MotionMode!=Default" "Label=Tolerancia de posición final"
TaskInfo: ArgDesc "Name=HeadingTolerance" "Parent=Move: Path" "Type=double" "Priority=Normal" "Desc=Máxima tolerancia permitida en grados entre la trayectoria final del AMR y la trayectoria final deseada." "Value=20" "Min=5" "Max=180" "Display=Visible:MotionMode!=Default" "Label=Tolerancia de trayectoria final"
TaskInfo: ArgDesc "Name=DebugMode" "Parent=Move: Path" "Type=string" "Priority=Detailed" "Desc=Especifica qué información de la tarea se registra para propósitos de depuración" "Value=Default" "Display=Choices:Default;;None;;Normal;;Moderate;;Extensive;;All" "Label=Modo de depuración"
TaskInfo: ArgDesc "Name=ClearanceMode" "Parent=Move: Path" "Type=string" "Priority=Detailed" "Desc=Especifica el área alrededor del AMR para la protección contra obstáculos durante el desplazamiento hasta la ubicación final" "Value=Default" "Display=Choices:Default;;Normal;;Variable;;Custom" "Label=Modo de espacio libre"
TaskInfo: ArgDesc "Name=ApproachDistance" "Parent=Move: Path" "Type=double" "Priority=Detailed" "Desc=Especifica la distancia mínima en mm a la que el AMR debería detenerse al aproximarse a un obstáculo" "Value=1000" "Min=100" "Max=8000" "Display=Visible:ClearanceMode!=Normal&&Visible:ClearanceMode!=Default&&Visible:ClearanceMode!=Default" "Label=Distancia de aproximación"
TaskInfo: ArgDesc "Name=TaxiLineApproachDistance" "Parent=Move: Path" "Type=double" "Priority=Detailed" "Desc=" "Value=1000" "Min=100" "Max=8000" "Display=Visible:ClearanceMode!=Normal&&Visible:ClearanceMode!=Default&&Visible:false&&Visible:ClearanceMode!=Default" "Label=TaxiLineApproachDistance"
TaskInfo: ArgDesc "Name=VirtualObstaclesAreReal" "Parent=Move: Path" "Type=bool" "Priority=Detailed" "Desc=Trata los obstáculos virtuales (áreas prohibidas, etc.) como obstáculos reales" "Value=false" "Display=Checkbox&&Visible:false" "Label=Los obstáculos virtuales son reales"
TaskInfo: ArgDesc "Name=ClearanceShape" "Parent=Move: Path" "Type=string" "Priority=Detailed" "Desc=Especifica la forma de la huella del AMR para la protección contra obstáculos" "Value=Normal" "Display=Choices:Normal;;Tight;;Expanded;;Custom;;Polygon&&Visible:ClearanceMode!=Default" "Label=Forma del espacio libre"
TaskInfo: ArgDesc "Name=FrontClearance" "Parent=Move: Path" "Type=double" "Priority=Detailed" "Desc=Especifica la longitud en mm de la zona de espacio libre delantera desde el borde delantero del AMR" "Value=0" "Min=-2500" "Max=1000" "Display=Visible:ClearanceShape=Custom&&Visible:ClearanceMode!=Default" "Label=Espacio libre delantero"
TaskInfo: ArgDesc "Name=LeftClearance" "Parent=Move: Path" "Type=double" "Priority=Detailed" "Desc=Especifica la longitud en mm de la zona de espacio libre izquierda desde el borde izquierdo del AMR" "Value=0" "Min=-2500" "Max=1000" "Display=Visible:ClearanceShape=Custom&&Visible:ClearanceMode!=Default" "Label=Espacio libre izquierdo"
TaskInfo: ArgDesc "Name=RightClearance" "Parent=Move: Path" "Type=double" "Priority=Detailed" "Desc=Especifica la longitud en mm de la zona de espacio libre derecha desde el borde derecho del AMR" "Value=0" "Min=-2500" "Max=1000" "Display=Visible:ClearanceShape=Custom&&Visible:ClearanceMode!=Default" "Label=Espacio libre derecho"
TaskInfo: ArgDesc "Name=BackClearance" "Parent=Move: Path" "Type=double" "Priority=Detailed" "Desc=Especifica la longitud en mm de la zona de espacio libre trasera desde el borde trasero del AMR" "Value=0" "Min=-2500" "Max=1000" "Display=Visible:ClearanceShape=Custom&&Visible:ClearanceMode!=Default" "Label=Espacio libre trasero"
TaskInfo: ArgDesc "Name=ClearanceSwitchDistance" "Parent=Move: Path" "Type=double" "Priority=Detailed" "Desc=Especifica la distancia en mm desde la posición final deseada a la que el AMR pasará a utilizar los espacios libres internos definidos" "Value=1500" "Min=0" "Max=3000" "Display=Visible:false" "Label=Distancia de conmutación de espacio libre"
TaskInfo: ArgDesc "Name=FinalClearanceShape" "Parent=Move: Path" "Type=string" "Priority=Detailed" "Desc=Especifica la forma de la huella del AMR para la protección contra obstáculos durante el movimiento final" "Value=Normal" "Display=Choices:Normal;;Tight;;Expanded;;Custom&&Visible:false" "Label=Forma del espacio libre final"
TaskInfo: ArgDesc "Name=FinalFrontClearance" "Parent=Move: Path" "Type=double" "Priority=Detailed" "Desc=Especifica la longitud en mm de la zona de espacio libre delantera desde el borde delantero del AMR" "Value=0" "Min=-400" "Max=1000" "Display=Visible:FinalClearanceShape=Custom&&Visible:ClearanceMode!=Default" "Label=Espacio libre delantero final"
TaskInfo: ArgDesc "Name=FinalLeftClearance" "Parent=Move: Path" "Type=double" "Priority=Detailed" "Desc=Especifica la longitud en mm de la zona de espacio libre izquierda desde el borde izquierdo del AMR" "Value=0" "Min=-400" "Max=1000" "Display=Visible:FinalClearanceShape=Custom&&Visible:ClearanceMode!=Default" "Label=Espacio libre izquierdo final"
