TaskInfo: TaskDesc "Name=Move: Segment" "Desc=Motion that is composed of small segments" "Class=Movement"
TaskInfo: ArgDesc "Name=MotionMode" "Parent=Move: Segment" "Type=string" "Priority=Important" "Desc=Especifica el tipo de movimiento utilizado durante la ejecución de la tarea." "Value=Move" "Display=Choices:Move;;DeltaHeading;;SetHeading;;Arc" "Label=Modo de movimiento"
TaskInfo: ArgDesc "Name=Distance" "Parent=Move: Segment" "Type=double" "Priority=Important" "Desc=La distancia que se moverá el AMR en mm desde la ubicación inicial. El movimiento es paralelo al eje X principal del marco de coordenadas del AMR." "Value=1000" "Display=Visible:MotionMode=Move" "Label=Distancia"
TaskInfo: ArgDesc "Name=DeltaAngle" "Parent=Move: Segment" "Type=double" "Priority=Important" "Desc=Especifica el cambio de rumbo relativo deseado al rumbo actual del AMR en grados. Utiliza valores positivos para girar el AMR hacia la izquierda/en el sentido contrario a las agujas del reloj. Valores negativos para girar el AMR hacia la derecha/en el sentido de las agujas del reloj." "Value=0" "Display=Visible:MotionMode=DeltaHeading" "Label=DeltaAngle"
TaskInfo: ArgDesc "Name=AbsoluteAngle" "Parent=Move: Segment" "Type=double" "Priority=Important" "Desc=La trayectoria total en grados con la que se alineará el AMR." "Value=0" "Min=-180" "Max=180" "Display=Visible:MotionMode=SetHeading" "Label=AbsoluteAngle"
TaskInfo: ArgDesc "Name=Radius" "Parent=Move: Segment" "Type=double" "Priority=Important" "Desc=" "Value=0" "Min=-50000" "Max=50000" "Display=Visible:MotionMode=Arc" "Label=Radius"
TaskInfo: ArgDesc "Name=TravelAngle" "Parent=Move: Segment" "Type=double" "Priority=Important" "Desc=" "Value=0" "Min=-360" "Max=360" "Display=Visible:MotionMode=Arc" "Label=TravelAngle"
TaskInfo: ArgDesc "Name=ObstacleMode" "Parent=Move: Segment" "Type=string" "Priority=Normal" "Desc=Especifica la manera en que se gestionan los obstáculos durante la ejecución de la tarea" "Value=Wait" "Display=Choices:None;;Wait" "Label=Modo obstáculo"
TaskInfo: ArgDesc "Name=Timeout" "Parent=Move: Segment" "Type=int" "Priority=Normal" "Desc=Tiempo transcurrido en segundos desde que el AMR se detuvo por un obstáculo antes de que la Tarea falle." "Value=400" "Min=1" "Max=54000" "Display=Visible:Radius!=None" "Label=Tiempo de espera"
TaskInfo: ArgDesc "Name=PositionTolerance" "Parent=Move: Segment" "Type=double" "Priority=Normal" "Desc=Máxima tolerancia permitida en mm entre la posición final del AMR y la posición final deseada." "Value=200" "Min=100" "Max=4000" "Label=Tolerancia de posición final"
TaskInfo: ArgDesc "Name=HeadingTolerance" "Parent=Move: Segment" "Type=double" "Priority=Normal" "Desc=Máxima tolerancia permitida en grados entre la trayectoria final del AMR y la trayectoria final deseada." "Value=20" "Min=5" "Max=180" "Label=Tolerancia de trayectoria final"
