TaskInfo: ArgDesc "Name=importance level" "Parent=playInstant" "Type=string" "Priority=Detailed" "Desc=Nivel de importancia de este elemento. Otras podrían cancelar este elemento para reproducir sonido o voz con un nivel de importancia superior." "Value=Normal" "Display=Choices:Most Important;;More Important;;Normal;;Less Important;;Least Important" "Label=nivel de importancia"
TaskInfo: ArgDesc "Name=cancel less important" "Parent=playInstant" "Type=bool" "Priority=Detailed" "Desc=Cancelar otros elementos de sonido y voz no reproducidos que tienen un nivel de importancia inferior al de este elemento." "Value=true" "Label=cancelar menos importante"
TaskInfo: ArgDesc "Name=repetition time threshold" "Parent=playInstant" "Type=double" "Priority=Detailed" "Desc=No realice esta tarea si una tarea con el mismo contenido de voz o sonido se ha llevado a cabo en esta cantidad de segundos. Use esto para evitar una repetición molesta de la misma reproducción de sonido o voz. Use 0.0 para llevar a cabo la tarea siempre." "Value=0" "Label=umbral de tiempo de repetición"
TaskInfo: TaskDesc "Name=popupSimple" "Desc=Solicita que las aplicaciones del cliente muestren un mensaje emergente sencillo. (Las aplicaciones del cliente incluyen MobilePlanner y MobileEyes)." "Class=Instant"
TaskInfo: ArgDesc "Name=Title" "Parent=popupSimple" "Type=string" "Priority=Important" "Desc=Título del mensaje emergente. Si está en blanco, se omite la casilla «No volver a mostrar»." "Value=" "Label=Título"
TaskInfo: ArgDesc "Name=Message" "Parent=popupSimple" "Type=string" "Priority=Important" "Desc=Mensaje que se mostrará en el mensaje emergente. Se debe especificar." "Value=" "Label=Mensaje"
TaskInfo: ArgDesc "Name=Button label" "Parent=popupSimple" "Type=string" "Priority=Important" "Desc=Etiqueta en el botón del mensaje emergente." "Value=OK" "Label=Etiqueta de botón"
TaskInfo: ArgDesc "Name=Button timeout" "Parent=popupSimple" "Type=int" "Priority=Important" "Desc=Duración (en segundos) del mensaje emergente. 0 significa que la ventana emergente debe mostrarse hasta que se presione el botón." "Value=0" "Min=0" "Max=65536" "Label=Tiempo de espera del botón"
TaskInfo: TaskDesc "Name=PrecisionDrive" "Desc=Conduce el AMR hasta una ubicación relativa a un objetivo especificado" "Class=Movement"
TaskInfo: ArgDesc "Name=TargetShape" "Parent=PrecisionDrive" "Type=string" "Priority=Important" "Desc=Especifica la silueta del objetivo que se hace coincidir con los datos del sensor de rango del AMR" "Value=Standard" "Display=Choices:StandardCopy;;StandardReverseCopy;;SimpleOpenTarget;;Standard;;StandardReverse;;DockLD;;DockHD" "Label=Silueta del objetivo"
TaskInfo: ArgDesc "Name=FinalOffsetX" "Parent=PrecisionDrive" "Type=double" "Priority=Important" "Desc=Distancia axial final en mm desde el centro del objetivo hasta el centro del AMR en el sistema de coordenadas del objetivo especificado" "Value=-1000" "Min=-4000" "Max=4000" "Label=Compensación final en X"
TaskInfo: ArgDesc "Name=FinalOffsetY" "Parent=PrecisionDrive" "Type=double" "Priority=Normal" "Desc=Distancia lateral final en mm desde el centro del objetivo hasta el centro del AMR en el sistema de coordenadas del objetivo especificado" "Value=0" "Min=-4000" "Max=4000" "Label=Compensación final en Y"
TaskInfo: ArgDesc "Name=FinalOffsetAngle" "Parent=PrecisionDrive" "Type=double" "Priority=Normal" "Desc=Rotación final en grados desde el centro del objetivo hasta el centro del AMR en el sistema de coordenadas del objetivo especificado" "Value=0" "Min=-200" "Max=200" "Label=Ángulo de compensación final"
TaskInfo: ArgDesc "Name=InitialX" "Parent=PrecisionDrive" "Type=double" "Priority=Important" "Desc=Distancia axial inicial en mm desde el centro del objetivo hasta el centro del AMR en el sistema de coordenadas del objetivo especificado" "Value=-2000" "Min=-4000" "Max=4000" "Label=X inicial"
TaskInfo: ArgDesc "Name=InitialY" "Parent=PrecisionDrive" "Type=double" "Priority=Normal" "Desc=Distancia lateral inicial en mm desde el centro del objetivo hasta el centro del AMR en el sistema de coordenadas del objetivo especificado" "Value=0" "Min=-4000" "Max=4000" "Label=Y inicial"
TaskInfo: ArgDesc "Name=InitialAngle" "Parent=PrecisionDrive" "Type=double" "Priority=Normal" "Desc=Rotación inicial en grados desde el centro del objetivo hasta el centro del AMR en el sistema de coordenadas del objetivo especificado" "Value=0" "Min=-180" "Max=180" "Label=Ángulo inicial"
TaskInfo: ArgDesc "Name=ParameterMode" "Parent=PrecisionDrive" "Type=string" "Priority=Detailed" "Desc=Conmuta la visibilidad de parámetros avanzados" "Value=Normal" "Display=Choices:Normal;;Advanced" "Label=Modo de parámetro"
TaskInfo: ArgDesc "Name=Timeout" "Parent=PrecisionDrive" "Type=int" "Priority=Detailed" "Desc=Tiempo transcurrido en segundos desde el inicio de la tarea antes del fallo" "Value=60" "Min=10" "Max=54000" "Display=Visible:ParameterMode=Advanced" "Label=Tiempo de espera"
TaskInfo: ArgDesc "Name=PathShape" "Parent=PrecisionDrive" "Type=string" "Priority=Detailed" "Desc=Especifica la silueta de la ruta que recorre el AMR hasta su ubicación final" "Value=PreAlign" "Display=Choices:PreAlign;;Straight;;PreAlign2&&Visible:ParameterMode=Advanced" "Label=Silueta de la ruta"
TaskInfo: ArgDesc "Name=SearchMode" "Parent=PrecisionDrive" "Type=string" "Priority=Detailed" "Desc=Especifica el tamaño del área de búsqueda del objetivo que rodea la ubicación inicial" "Value=Normal" "Display=Choices:Normal;;Wide;;Tall;;Minimum;;Maximum;;Rotation&&Visible:ParameterMode=Advanced" "Label=Modo de búsqueda"
TaskInfo: ArgDesc "Name=MatchMode" "Parent=PrecisionDrive" "Type=string" "Priority=Detailed" "Desc=Especifica la desviación permitida entre la silueta ideal del objetivo y la silueta detectada" "Value=Normal" "Display=Choices:Normal;;Lenient;;Strict&&Visible:ParameterMode=Advanced" "Label=Modo de coincidencia"
TaskInfo: ArgDesc "Name=FailMode" "Parent=PrecisionDrive" "Type=string" "Priority=Detailed" "Desc=Especifica las condiciones anormales que causan que la tarea falle inmediatamente" "Value=None" "Display=Choices:None;;FailOnEstop&&Visible:ParameterMode=Advanced" "Label=Modo de fallo"
TaskInfo: ArgDesc "Name=DebugMode" "Parent=PrecisionDrive" "Type=string" "Priority=Detailed" "Desc=Especifica qué información de la tarea se registra para propósitos de depuración" "Value=Normal" "Display=Visible:ParameterMode=Advanced&&Choices:None;;Normal;;Moderate;;Extensive;;All" "Label=Modo de depuración"
TaskInfo: ArgDesc "Name=ClearanceMode" "Parent=PrecisionDrive" "Type=string" "Priority=Detailed" "Desc=Especifica el área alrededor del AMR para la protección contra obstáculos durante el desplazamiento hasta la ubicación final" "Value=Normal" "Display=Visible:ParameterMode=Advanced&&Choices:Normal;;Variable;;Custom" "Label=Modo de espacio libre"
TaskInfo: ArgDesc "Name=ApproachDistance" "Parent=PrecisionDrive" "Type=double" "Priority=Detailed" "Desc=Especifica la distancia mínima en mm a la que el AMR debería detenerse al aproximarse a un obstáculo" "Value=1000" "Min=100" "Max=8000" "Display=Visible:ClearanceMode!=Normal" "Label=Distancia de aproximación"
TaskInfo: ArgDesc "Name=VirtualObstaclesAreReal" "Parent=PrecisionDrive" "Type=bool" "Priority=Detailed" "Desc=Trata los obstáculos virtuales (áreas prohibidas, etc.) como obstáculos reales" "Value=true" "Display=Checkbox&&Visible:false" "Label=Los obstáculos virtuales son reales"
TaskInfo: ArgDesc "Name=ClearanceShape" "Parent=PrecisionDrive" "Type=string" "Priority=Detailed" "Desc=Especifica la forma de la huella del AMR para la protección contra obstáculos" "Value=Normal" "Display=Choices:Normal;;Tight;;Expanded;;Custom&&Visible:ParameterMode=Advanced" "Label=Forma del espacio libre"
TaskInfo: ArgDesc "Name=FrontClearance" "Parent=PrecisionDrive" "Type=double" "Priority=Detailed" "Desc=Especifica la longitud en mm de la zona de espacio libre delantera desde el borde delantero del AMR" "Value=50" "Min=-600" "Max=1000" "Display=Visible:ClearanceShape=Custom&&Visible:ParameterMode=Advanced" "Label=Espacio libre delantero"
TaskInfo: ArgDesc "Name=LeftClearance" "Parent=PrecisionDrive" "Type=double" "Priority=Detailed" "Desc=Especifica la longitud en mm de la zona de espacio libre izquierda desde el borde izquierdo del AMR" "Value=75" "Min=-600" "Max=1000" "Display=Visible:ClearanceShape=Custom&&Visible:ParameterMode=Advanced" "Label=Espacio libre izquierdo"
TaskInfo: ArgDesc "Name=RightClearance" "Parent=PrecisionDrive" "Type=double" "Priority=Detailed" "Desc=Especifica la longitud en mm de la zona de espacio libre derecha desde el borde derecho del AMR" "Value=75" "Min=-600" "Max=1000" "Display=Visible:ClearanceShape=Custom&&Visible:ParameterMode=Advanced" "Label=Espacio libre derecho"
TaskInfo: ArgDesc "Name=BackClearance" "Parent=PrecisionDrive" "Type=double" "Priority=Detailed" "Desc=Especifica la longitud en mm de la zona de espacio libre trasera desde el borde trasero del AMR" "Value=20" "Min=-600" "Max=1000" "Display=Visible:ClearanceShape=Custom&&Visible:ParameterMode=Advanced" "Label=Espacio libre trasero"
TaskInfo: ArgDesc "Name=ClearanceSwitchDistance" "Parent=PrecisionDrive" "Type=double" "Priority=Detailed" "Desc=Especifica la distancia en mm desde la posición final deseada a la que el AMR pasará a utilizar los espacios libres internos definidos" "Value=300" "Min=0" "Max=3000" "Display=Visible:ClearanceMode=Variable&&Visible:ParameterMode=Advanced" "Label=Distancia de conmutación de espacio libre"
TaskInfo: ArgDesc "Name=FinalClearanceShape" "Parent=PrecisionDrive" "Type=string" "Priority=Detailed" "Desc=Especifica la forma de la huella del AMR para la protección contra obstáculos durante el movimiento final" "Value=Normal" "Display=Choices:Normal;;Tight;;Expanded;;Custom&&Visible:ClearanceMode=Variable&&Visible:ParameterMode=Advanced" "Label=Forma del espacio libre final"
TaskInfo: ArgDesc "Name=FinalFrontClearance" "Parent=PrecisionDrive" "Type=double" "Priority=Detailed" "Desc=Especifica la longitud en mm de la zona de espacio libre delantera desde el borde delantero del AMR" "Value=50" "Min=-400" "Max=1000" "Display=Visible:ClearanceMode=Variable&&Visible:FinalClearanceShape=Custom" "Label=Espacio libre delantero final"
TaskInfo: ArgDesc "Name=FinalLeftClearance" "Parent=PrecisionDrive" "Type=double" "Priority=Detailed" "Desc=Especifica la longitud en mm de la zona de espacio libre izquierda desde el borde izquierdo del AMR" "Value=50" "Min=-400" "Max=1000" "Display=Visible:ClearanceMode=Variable&&Visible:FinalClearanceShape=Custom" "Label=Espacio libre izquierdo final"
TaskInfo: ArgDesc "Name=FinalRightClearance" "Parent=PrecisionDrive" "Type=double" "Priority=Detailed" "Desc=Especifica la longitud en mm de la zona de espacio libre derecha desde el borde derecho del AMR" "Value=50" "Min=-400" "Max=1000" "Display=Visible:ClearanceMode=Variable&&Visible:FinalClearanceShape=Custom" "Label=Espacio libre derecho final"
TaskInfo: ArgDesc "Name=FinalBackClearance" "Parent=PrecisionDrive" "Type=double" "Priority=Detailed" "Desc=Especifica la longitud en mm de la zona de espacio libre trasera desde el borde trasero del AMR" "Value=50" "Min=-400" "Max=1000" "Display=Visible:ClearanceMode=Variable&&Visible:FinalClearanceShape=Custom" "Label=Espacio libre trasero final"
TaskInfo: ArgDesc "Name=DriveMode" "Parent=PrecisionDrive" "Type=string" "Priority=Detailed" "Desc=Especifica la forma en la que se optimiza el movimiento de conducción" "Value=Normal" "Display=Visible:ParameterMode=Advanced&&Choices:Normal;;Smooth;;Precise;;Fast" "Label=Modo de conducción"
TaskInfo: ArgDesc "Name=TranslationalSpeed" "Parent=PrecisionDrive" "Type=double" "Priority=Detailed" "Desc=Límite de velocidad de translación en mm/s" "Value=100" "Min=20" "Max=500" "Display=Visible:ParameterMode=Advanced&&" "Label=Velocidad de traslación"
TaskInfo: ArgDesc "Name=ForwardSpeed" "Parent=PrecisionDrive" "Type=double" "Priority=Detailed" "Desc=Límite de velocidad de translación hacia delante en mm/s" "Value=100" "Min=20" "Max=500" "Display=Visible:false" "Label=Velocidad de avance"
TaskInfo: ArgDesc "Name=ReverseSpeed" "Parent=PrecisionDrive" "Type=double" "Priority=Detailed" "Desc=Límite de velocidad de translación en marcha atrás en mm/s" "Value=-100" "Min=-200" "Max=-50" "Display=Visible:false" "Label=Velocidad en marcha atrás"
TaskInfo: ArgDesc "Name=RotationalSpeed" "Parent=PrecisionDrive" "Type=double" "Priority=Detailed" "Desc=Límite de velocidad de rotación en grados/s" "Value=30" "Min=2" "Max=50" "Display=Visible:ParameterMode=Advanced" "Label=Velocidad de rotación"
TaskInfo: ArgDesc "Name=PrimaryLaser" "Parent=PrecisionDrive" "Type=string" "Priority=Detailed" "Desc=Especifica por número qué escáner láser utilizará el AMR para encontrar el objetivo." "Value=Laser_1" "Display=Choices:Laser_1;;Laser_2;;Laser_3;;Laser_4;;Laser_5;;Laser_6&&Visible:ParameterMode=Advanced" "Label=PrimaryLaser"
TaskInfo: ArgDesc "Name=IgnoreDistance" "Parent=PrecisionDrive" "Type=double" "Priority=Normal" "Desc=Especifica la distancia en mm desde la posición final deseada a la que el AMR dejará de utilizar el objetivo para recibir información sobre la posición." "Value=0" "Min=0" "Max=10000" "Display=Visible:ParameterMode=Advanced" "Label=IgnoreDistance"
TaskInfo: ArgDesc "Name=IgnoreFinalHeading" "Parent=PrecisionDrive" "Type=bool" "Priority=Normal" "Desc=" "Value=false" "Display=Checkbox&&Visible:ParameterMode=Advanced" "Label=IgnoreFinalHeading"
TaskInfo: ArgDesc "Name=TaskRequiresCAPS" "Parent=PrecisionDrive" "Type=bool" "Priority=Normal" "Desc=Comprueba si la Tarea requiere una licencia CAPS para proceder." "Value=false" "Display=Checkbox&&Visible:ParameterMode=Advanced" "Label=TaskRequiresCAPS"
TaskInfo: TaskDesc "Name=recordSoundFile" "Desc=Graba sonido en un archivo WAV en el robot durante un periodo" "Class=Audio"
TaskInfo: ArgDesc "Name=file name" "Parent=recordSoundFile" "Type=string" "Priority=Important" "Desc=Nombre de archivo de sonido (archivo WAV). (Códigos especiales: $g=nombre del objetivo. Posición actual del robot $X (x en mm) $Y (y en mm) $T (rumbo en grados, -180 to 180). Hora en GMT: $y=año actual, $m=mes, $d=día, $H=hora, $M=minuto, $S=segundo." "Value=$g-$y$m$d_$H$M$S.wav" "Label=nombre de archivo"
TaskInfo: ArgDesc "Name=duration" "Parent=recordSoundFile" "Type=double" "Priority=Important" "Desc=Tiempo que se grabará, en segundos." "Value=5" "Min=0" "Max=120" "Label=Duración"
TaskInfo: TaskDesc "Name=RobotShapeSet" "Desc=sets the the robot's shape" "Class=Instant"
TaskInfo: ArgDesc "Name=Which" "Parent=RobotShapeSet" "Type=string" "Priority=Detailed" "Desc=Especifica qué forma basada en polígonos se modificará en la Tarea." "Value=Both" "Display=Choices:Shape;;Clearances;;Both" "Label=Tipo de forma"
