TaskInfo: TaskDesc "Name=SendText" "Desc=Envía el texto especificado a todos los clientes." "Class=Instant" "Label=Sección"
TaskInfo: ArgDesc "Name=key" "Parent=SendText" "Type=string" "Priority=Important" "Desc=Identificador de texto del mensaje." "Value=" "Display=RegExp:^[\w \u2000-\u206F\u2E00-\u2E7F\'!"#$%&()*+,\-.\/:;<=>?@\[\]^_`{|}~]{0,250}$" "Label=clave"
TaskInfo: ArgDesc "Name=message" "Parent=SendText" "Type=string" "Priority=Important" "Desc=Texto que se enviará." "Value=" "Display=RegExp:^[\w \u2000-\u206F\u2E00-\u2E7F\'!"#$%&()*+,\-.\/:;<=>?@\[\]^_`{|}~]{0,250}$" "Label=mensaje"
TaskInfo: TaskDesc "Name=SensorCheckPolygon" "Desc=Checks a region for sensor data points" "Class=Sensor"
TaskInfo: ArgDesc "Name=CheckPolygonMode" "Parent=SensorCheckPolygon" "Type=string" "Priority=Normal" "Desc=Configure behavior of the check polygon task" "Value=CheckEmpty" "Display=Choices:CheckEmpty;;CheckOccupied" "Label=CheckPolygonMode"
