TaskInfo: TaskDesc "Name=setHeading" "Desc=Gira hacia un rumbo/orientación global específico." "Class=Movement|Heading"
TaskInfo: ArgDesc "Name=heading" "Parent=setHeading" "Type=int" "Priority=Important" "Desc=Rumbo global (en grados) al cual girar." "Value=0" "Min=-180" "Max=180" "Label=rumbo"
TaskInfo: ArgDesc "Name=rotVelMax" "Parent=setHeading" "Type=int" "Priority=Detailed" "Desc=Velocidad de rotación máxima (en grados/s) al girar. 0 significa que se usa el valor por defecto." "Value=0" "Min=0" "Label=rotVelMax"
TaskInfo: ArgDesc "Name=rotAccel" "Parent=setHeading" "Type=int" "Priority=Detailed" "Desc=Aceleración de rotación (en grados/s/s) al girar. 0 significa que se usa el valor por defecto." "Value=0" "Min=0" "Label=rotAccel"
TaskInfo: ArgDesc "Name=rotDecel" "Parent=setHeading" "Type=int" "Priority=Detailed" "Desc=Desaceleración de rotación (en grados/s/s) al girar. 0 significa que se usa el valor por defecto." "Value=0" "Min=0" "Label=rotDecel"
TaskInfo: ArgDesc "Name=time until fail" "Parent=setHeading" "Type=int" "Priority=Detailed" "Desc=Tiempo de espera (en segundos) si no es posible girar antes de declarar que la tarea ha fallado." "Value=30" "Min=0" "Label=tiempo antes de fallo"
TaskInfo: ArgDesc "Name=minimum time" "Parent=setHeading" "Type=int" "Priority=Detailed" "Desc=Duración mínima (en segundos) para esta tarea. Si el robot alcanza su destino en menos tiempo, la tarea espera el recordatorio de la duración. 0 significa que la tarea debería completarse en cuanto el robot llegue a su rumbo de destino." "Value=0" "Min=0" "Label=tiempo mínimo"
TaskInfo: TaskDesc "Name=wait" "Desc=Espera el número de segundos especificado. Esta espera puede ser interrumpida por un comando de reanudación explícito." "Class=Timing"
TaskInfo: ArgDesc "Name=seconds to wait" "Parent=wait" "Type=int" "Priority=Important" "Desc=Número de segundos que se espera." "Value=5" "Min=1" "Label=segundos que se espera"
TaskInfo: ArgDesc "Name=status to wait with" "Parent=wait" "Type=string" "Priority=Detailed" "Desc=Mensaje de estado que se transmitirá durante la espera." "Value=Waiting" "Label=estado con el cual esperar"
TaskInfo: ArgDesc "Name=premotion blink" "Parent=wait" "Type=bool" "Priority=Detailed" "Desc=Cuando está habilitado (verdadero), el robot realiza la acción de parpadeo previo al movimiento durante el período de espera." "Value=false" "Label=parpadeo previo al movimiento"
TaskInfo: TaskDesc "Name=waitActive" "Desc=Invoca una macro y opcionalmente espera un número dado de segundos o hasta que se le indica continuar mediante comando y control" "Class=Timing"
TaskInfo: ArgDesc "Name=wait type" "Parent=waitActive" "Type=string" "Priority=Detailed" "Desc=El tipo de espera. Longitud especificada: invoca la macro (si corresponde) y espera hasta que se agota el tiempo de espera. Si la macro no finaliza durante el tiempo de espera, aborta. Longitud de la macro: invoca la macro (si corresponde) y finaliza. Para siempre: invoca la macro (si corresponde) y aguarda indefinidamente (hasta que se cancela la tarea)." "Value=Specified length" "Display=Choices:Specified length;;Macro length;;Forever" "Label=tipo de espera"
TaskInfo: ArgDesc "Name=seconds to wait" "Parent=waitActive" "Type=int" "Priority=Important" "Desc=El número de segundos que se espera" "Value=5" "Min=1" "Label=segundos que se espera"
TaskInfo: ArgDesc "Name=status to wait with" "Parent=waitActive" "Type=string" "Priority=Detailed" "Desc=El mensaje de estado que se tiene mientras se espera" "Value=Waiting" "Label=estado con el cual esperar"
TaskInfo: ArgDesc "Name=premotion blink" "Parent=waitActive" "Type=bool" "Priority=Detailed" "Desc=Define si se realiza o no el parpadeo previo al movimiento mientras se espera" "Value=false" "Label=parpadeo previo al movimiento"
TaskInfo: ArgDesc "Name=macro" "Parent=waitActive" "Type=string" "Priority=Normal" "Desc=la macro (si corresponde) que se invoca durante la secuencia de espera" "Value=" "Display=Macro" "Label=macro"
TaskInfo: ArgDesc "Name=lockMode" "Parent=waitActive" "Type=bool" "Priority=Normal" "Desc=Define si se bloquea el modo.  Si se encuentra bloqueado, permanecerá bloqueado hasta que la espera se cancele o falle." "Value=false" "Display=Checkbox" "Label=lockMode"
TaskInfo: ArgDesc "Name=succeeded macro" "Parent=waitActive" "Type=string" "Priority=Normal" "Desc=la macro (si corresponde) que se invoca después de que la espera finalice correctamente (una espera cancelada se considera correcta)" "Value=" "Display=Macro" "Label=macro correcta"
TaskInfo: ArgDesc "Name=failed macro" "Parent=waitActive" "Type=string" "Priority=Normal" "Desc=la macro (si corresponde) que se invoca después de que la espera falle" "Value=" "Display=Macro" "Label=macro fallida"
TaskInfo: TaskDesc "Name=waitCancel" "Desc=Cancela toda espera en curso (haciendo que sea correcta)" "Class=Instant"
TaskInfo: TaskDesc "Name=waitFail" "Desc=Hace fallar toda espera en curso" "Class=Instant"
TaskInfo: TaskDesc "Name=waitIndefinitely" "Desc=Espera hasta que se le ordena lo contrario" "Class=Timing"
TaskInfo: ArgDesc "Name=status to pause with" "Parent=waitIndefinitely" "Type=string" "Priority=Detailed" "Desc=El mensaje de estado que se tiene mientras se está en pausa" "Value=Pausing" "Label=estado con el que hacer pausa"
